update content_bodies set title = 'The Sacred Place of Sake: Hida Takayama', description = 'This video introduces Hida Takayama, known as the sacred place of sake. The ''Hida Takayama Sake Brewery Nonbei Festival'' features a stamp rally where participants can enjoy tastings of two types of sake at six different breweries. The event also offers special benefits, including a commemorative cup and a special eco-bag.' where id = 'JxCTTf4xOAmaHSC5jGaiN';
update content_bodies set title = '国府町の宇津江四十八滝公園の山野草花園でクリンソウが見頃', description = 'この動画では、国府町にある宇津江四十八滝公園の山野草花園でのクリンソウの見頃を紹介しています。木々の緑に映えるピンクや白の花々が美しく、園内の遊歩道は整備されているため、車イスの方も安心して訪れることができます。' where id = 'bJTXCCzppyLe9kRMGeDxR';
update content_bodies set title = 'The Primula Sieboldii in the Wildflower Garden of Uzu-e 48 Waterfalls Park', description = 'This video showcases the blooming Primula sieboldii in the wildflower garden located in Uzu-e 48 Waterfalls Park in Kōfu Town. The pink and white flowers stand out beautifully against the green trees. The park''s walking paths are well-maintained, making it accessible for wheelchair users.' where id = 'MmPCwbd8ESHu6tIxdmoQ2';
update content_bodies set title = '宮峠トンネルを抜けた瞬間に広がる飛騨一之宮の田園風景', description = 'この動画では、宮峠トンネルを抜けた瞬間に広がる飛騨一之宮の美しい田園風景を紹介しています。日中の気温が上昇し、徐々に夏の空に近づいている様子が感じられます。' where id = 'nKwjBZtaaddMChpNjyyI1';
update content_bodies set title = 'The Scenic Rural Landscape of Hida Ichinomiya Beyond the Miyatoge Tunnel', description = 'This video showcases the breathtaking rural scenery of Hida Ichinomiya that unfolds immediately after passing through the Miyatoge Tunnel. As daytime temperatures rise, the atmosphere gradually shifts towards the essence of summer.' where id = 'nmhLoa7nySlKfcvUCpeop';
update content_bodies set title = '古くから飛騨と信州を結ぶ重要なルート野麦峠', description = 'この動画は、古くから飛騨と信州を結ぶ重要なルートである野麦峠について紹介しています。5月26日には野麦峠まつりが行われ、工女の苦難を偲ぶために工女に扮した岐阜県と長野県の参加者が野麦峠で合流し、旧野麦街道を練り歩きました。' where id = 'pkwWy5xYo5X5HlFcCg4mo';
update content_bodies set title = 'The Important Route Connecting Hida and Shinshu: Nōmugi Pass', description = 'This video introduces Nōmugi Pass, an important route that has connected Hida and Shinshu since ancient times. On May 26, the Nōmugi Pass Festival was held, where participants dressed as factory girls commemorated their hardships. Participants from both Gifu and Nagano prefectures gathered at Nōmugi Pass and paraded along the old Nōmugi Road.' where id = 'T0DFMPa1gPI9QFbJ82A7u';
update content_bodies set title = '郡上市八幡町から高山市清見町三日町を結ぶ「飛騨美濃せせらぎ街道」', description = 'この動画では、郡上市八幡町から高山市清見町三日町を結ぶ「飛騨美濃せせらぎ街道」について紹介しています。このルートは、爽やかな風と新緑を楽しむのにぴったりのドライブコースです。' where id = 'JYI8VHG_dmmW5hI6xQZFK';
update content_bodies set title = 'Hida Minou Seseragi Road Connecting Gujo City Hachiman Town and Takayama City Kiyomi Town Mikata Town', description = 'This video introduces the ''Hida Minou Seseragi Road,'' which connects Gujo City Hachiman Town and Takayama City Kiyomi Town Mikata Town. It is an ideal route for a drive, allowing you to enjoy refreshing breezes and fresh greenery.' where id = 'EyA4MFKZLzpbERcUjqevo';
update content_bodies set title = '飛騨高山ジャズフェスティバル', description = 'この動画では、飛騨高山ジャズフェスティバルについて紹介しています。大自然の中で心躍る音楽を楽しみながら、美味しいお酒や美食を味わい、最高のひとときを過ごすことができます。' where id = '0IH8OFk3rWkwbrCkm6r86';
update content_bodies set title = 'Hida Takayama Jazz Festival', description = 'This video introduces the Hida Takayama Jazz Festival, where you can enjoy exhilarating music amidst the great outdoors, along with delicious food and drinks for a perfect experience.' where id = 'rJ3hydXk1JR9uS43mSQIT';
update content_bodies set title = '良質な飛騨牛を味わえる「肉の匠家 安川店」', description = 'この動画では、良質な飛騨牛を楽しめる「肉の匠家 安川店」について紹介しています。特に元祖飛騨牛まぶしの食べ方に焦点を当てており、1杯目はそのまま、2杯目は飛騨ネギとわさび、3杯目はお出汁をかけて楽しむ方法が説明されています。' where id = 'LzzsY_-ZPXmj9IdWwOtP4';
update content_bodies set title = 'Enjoy High-Quality Hida Beef at ''Niku no Takumiya Yasukawa''', description = 'This video introduces ''Niku no Takumiya Yasukawa'', a place where you can savor high-quality Hida beef. It also explains how to enjoy the original Hida beef mabu-shi, which involves three different ways of eating: the first bowl is enjoyed as is, the second with Hida green onions and wasabi, and the third with dashi poured over it.' where id = 'c3EtOKT9ZFbOW_KChhiFp';
update content_bodies set title = '飛騨一之宮の田園風景', description = 'この動画では、飛騨一之宮の田園風景を紹介しています。田んぼには水が張られ、いよいよ田植えの季節が到来しました。水田に映る空は、日本の原風景を感じさせる美しい光景です。' where id = 'RBvqRzuTluLwUDW9xwR5I';
update content_bodies set title = 'Rural Landscape of Hida Ichinomiya', description = 'This video introduces the rural landscape of Hida Ichinomiya, where rice fields are filled with water, marking the beginning of the rice planting season. The traditional Japanese scenery is beautifully reflected in the waterlogged rice paddies.' where id = 'Tn2GmM-wbcBBIjVTARAck';
update content_bodies set title = '合掌造りなど日本の美しい原風景と飛騨人の暮らしや文化を体験できる「飛騨の里」で展示されている巨大な和紙の鯉のぼりと五月人形', description = 'この動画では、合掌造りなどの美しい原風景と飛騨人の文化を体験できる「飛騨の里」で展示されている全長9m50cmの巨大な和紙の鯉のぼりと五月人形について紹介しています。特に、迫力満点の巨大な鯉のぼりが印象的です。' where id = 'EtXdTREeg6_Re3FpBPPcV';
update content_bodies set title = 'Experience the Beautiful Scenery and Culture of Hida at ''Hida no Sato'' with a Giant Paper Carp Streamer and May Doll', description = 'This video introduces the giant paper carp streamer, measuring 9.5 meters in length, and the May doll displayed at ''Hida no Sato,'' where visitors can experience the beautiful traditional scenery of Japan and the lifestyle and culture of the Hida people.' where id = 'IPSurt2---lhjZxnSOY5e';
update content_bodies set title = '古い町並と藤の花町歩きが楽しめる季節', description = 'この動画では、古い町並みの美しい景観と、鮮やかな紫色の藤の花が映える季節について紹介しています。飛騨高山の町を散策しながら、歴史的な雰囲気と自然の美しさを同時に楽しむことができる魅力的な時期です。' where id = 'hyt3IK_kehc4k1z_7g--S';
update content_bodies set title = 'A Season to Enjoy Strolling Through Historic Streets and Wisteria Flowers', description = 'This video introduces the season when you can enjoy walking through the historic streets and viewing the beautiful wisteria flowers.' where id = 'wwU5Q2lTLY2PqwPT8tZpu';
update content_bodies set title = '飛騨地域の豊かな自然から生み出される食材を使用したお寿司', description = 'この動画では、飛騨地域の豊かな自然から生み出される食材を使用したお寿司について紹介しています。古くから伝わる郷土のお寿司に加え、飛騨牛を使用したお寿司も楽しむことができます。特に人気のある「飛騨牛とろちらし」は、20食限定で提供されており、特別な味わいを楽しむことができます。' where id = 'TpRPeeEYW5JUoyvH_USX-';
update content_bodies set title = 'Sushi Made with Rich Ingredients from the Hida Region', description = 'This video introduces sushi made using ingredients from the rich natural environment of the Hida region, including traditional local sushi and sushi featuring Hida beef. The highlight is the popular limited edition ''Hida Beef Toro Chirashi,'' available in only 20 servings.' where id = 'RJRGh8e8uD1IUnislObB7';
update content_bodies set title = '飛騨一之宮の美しい桜', description = 'この動画では、飛騨一之宮の桜について紹介しています。臥龍桜だけでなく、町の至るところに美しい桜が咲き誇り、宮川堤には昭和20年代から整備された桜並木があり、カスミザラやエドヒガン、シダレザクラなどが満開です。' where id = 'G7S2zGYRN1S2BodBiTu3t';
update content_bodies set title = 'Hida Ichinomiya: Beautiful Cherry Blossoms in Full Bloom', description = 'This video introduces the cherry blossoms in Hida Ichinomiya, highlighting not only the famous Garyu-zakura but also the stunning cherry blossoms that bloom throughout the town. The Miyagawa embankment features a cherry blossom avenue that has been maintained since the 1940s, showcasing varieties such as Kasumizakura, Edohigan, and Shidarezakura in full bloom.' where id = 'B1mpjE3yxyvF6kGu_vwyy';
update content_bodies set title = '奥飛騨温泉郷 平湯温泉の桜の新名所「ひらゆさくら」が見頃をむかえています', description = 'この動画では、奥飛騨温泉郷平湯温泉にある桜の新名所「ひらゆさくら」について紹介しています。エドヒガンや八重彼岸など7種類の桜が500本咲き誇り、一面に広がるピンク色の景色は春の絶景を楽しませてくれます。' where id = 'gUN-EXJ1BM6EhCzb7dakU';
update content_bodies set title = 'New Cherry Blossom Spot ''Hirayusakura'' in Okuhida Onsen-go Hirayu Onsen is in Full Bloom', description = 'This video introduces ''Hirayusakura'', a new cherry blossom spot in Okuhida Onsen-go Hirayu Onsen. Featuring seven varieties of cherry blossoms, including Edohigan and Yaehigan, around 500 trees are in full bloom, creating a stunning pink landscape that embodies the beauty of spring.' where id = 'NakNyVnSZlawFl3Nr1S_7';
update content_bodies set title = '高山市の花でもある コバノミツバツツジ が見頃です', description = 'この動画では、高山市の花であるコバノミツバツツジについて紹介しています。現在、飛騨一之宮の御旅山では、可愛らしいピンクの花が満開です。JR飛騨一ノ宮駅から久々野方面に向かって線路沿いの道路を約5分ほど歩くと、御旅山に到着します。' where id = 'KSmouYn3G0d0opr8Qh_Ke';
update content_bodies set title = 'The Kobano Mitsuba Tsutsuji, the Flower of Takayama, is in Full Bloom', description = 'This video introduces the Kobano Mitsuba Tsutsuji, which is the flower of Takayama. The flowers are currently in full bloom at Mt. Otabiyama in Hida Ichinomiya, showcasing their lovely pink petals. To reach this location, one can walk about five minutes along the road next to the railway from JR Hida Ichinomiya Station towards Kuzukano.' where id = 'w4vPw_nppN7GPEg1Arpqz';
update content_bodies set title = '荘川村の伝統家屋「寄棟式入母屋合掌造り」など', description = 'この動画では、荘川村に伝わる伝統家屋「寄棟式入母屋合掌造り」などが移築保存されている「飛騨 荘川の里」について紹介しています。桜の花が咲き誇る中、昔ばなしに出てくるような幻想的な風景が広がっています。' where id = '_Y8ObkrKTfTvZvQruep5c';
update content_bodies set title = 'Traditional Houses of Shokawa Village: ''Yarimune-style Irimoya Gassho-zukuri'' and More', description = 'This video introduces ''Hida Shokawa no Sato'', where traditional houses such as the ''Yarimune-style Irimoya Gassho-zukuri'' are relocated and preserved. The scenery, with cherry blossoms in full bloom, creates a fantastical atmosphere reminiscent of old tales.' where id = '1uZ02hMp6fBuTOjdrlcu_';
update content_bodies set title = '津波被害から復興中の美しい海辺の温泉ホテル | 南三陸ホテル観洋', description = '南三陸ホテル観洋は、津波被害から復興中の町に位置する海辺の温泉ホテルです。仙台駅からの無料シャトルバスサービスがあり、ExpediaやHotels.com、Trip.com、Agodaなどのプラットフォームを通じて予約が可能です。2名2食付きの宿泊料金は35,200円からです。この動画では、ホテルのアメニティや屋上からの眺め、海辺の浴場、食事体験が紹介されています。また、災害時のホテルの歴史や被災地のバスツアーも含まれています。詳細はホテルのウェブサイトや公式オンラインストアをご覧ください。' where id = 'I36ef9BBVZzF9DehOpqmT';
update content_bodies set title = 'Beautiful Seaside Onsen Hotel in Town Recovering from Tsunami Damage | Minamisanriku Hotel Kanyo', description = 'Minamisanriku Hotel Kanyo is a seaside onsen hotel located in a town recovering from tsunami damage. The hotel offers a free shuttle bus service from Sendai Station and provides various booking options through platforms like Expedia, Hotels.com, Trip.com, and Agoda. Prices for a stay for two people with two meals start at 35,200 yen. The video showcases the hotel’s amenities, including a rooftop view, seaside baths, and dining experiences. It also highlights the hotel’s history during the disaster and includes a bus tour of the affected area. For more information, visit the hotel’s website or their official online store.' where id = 'ogUc2VjWr68tIbPmNOe7C';
update content_bodies set title = '青屋神明神社のライトアップ', description = 'この動画は青屋神明神社のライトアップについて紹介しています。県外からも多くの方が訪れるこのフォトスポットでは、大きな枝垂れ桜が目の前に広がる水田と共に、逆さに映る桜の美しさが圧倒的です。まるで鏡に映る別世界のような景色が広がり、訪れる人々を魅了しています。' where id = 'jW7SPWrx9u9ddfOug_6od';
update content_bodies set title = 'Illumination of Aoya Shinmei Shrine: A Photogenic Spot Drawing Visitors from Outside the Prefecture', description = 'This video introduces the illumination of Aoya Shinmei Shrine, a popular photogenic spot attracting many visitors from outside the prefecture. The shrine features a large weeping cherry tree in front of expansive rice fields, where the reflection of the cherry blossoms creates a stunningly beautiful inverted image. This mirrored world offers a breathtaking view.' where id = 'td7z6gP_mWJGKZI4Lt6Q0';
update content_bodies set title = '朝日町の桜が見頃を迎えています', description = 'この動画では、朝日町の桜について紹介しています。青屋神明神社にある大きな枝垂れ桜は、目の前に広がる水田とともに美しい景観を作り出しています。水面に映る逆さの桜は圧倒的な美しさを誇り、朝日町を代表する枝垂れ桜の一つです。' where id = '9A8q9zqXsWZ63yVv2p7HM';
update content_bodies set title = 'The Cherry Blossoms in Asahi Town are at Their Peak', description = 'This video introduces the cherry blossoms in Asahi Town. The large weeping cherry tree at Aoya Shinmei Shrine stands out, with rice fields stretching out in front of it. The reflection of the cherry blossoms in the water creates an overwhelming beauty. This tree is one of the most representative weeping cherry trees in Asahi Town.' where id = 'YX4oyiViHuVN8Grj2xYty';
update content_bodies set title = 'カンカコカンでおなじみの「闘鶏楽」', description = 'この動画では、カンカコカンで知られる「闘鶏楽」について紹介しています。白地に色鮮やかな鳳凰の衣装が目を引き、鳴り響く鐘の音色が祭りの雰囲気を一層盛り上げています。' where id = 'r529R3HNoSQZcI-gvkJN-';
update content_bodies set title = 'Toukeiraku, Known for Kankakokan', description = 'This video introduces ''Toukeiraku,'' famous for its Kankakokan. The vibrant phoenix costumes on a white background catch the eye, while the ringing of bells enhances the festive atmosphere.' where id = 'Kux4I4-puAiM-u7XAvsad';
update content_bodies set title = '夜祭', description = 'この動画では夜祭について紹介しています。夜祭では、約100個の提灯を灯した各屋台が町をゆっくりと巡り、順道場を過ぎると「高い山」という曳き別れ歌を歌いながら各屋台蔵へ帰っていきます。昼とは異なる幻想的な雰囲気が魅力です。' where id = 'eB_Jada73cVwRrxxCrrbn';
update content_bodies set title = 'Night Festival', description = 'This video introduces the Night Festival, where each float, adorned with approximately 100 lanterns, slowly parades through the town. After passing the ''Jundō Hall,'' the floats return to their respective storage houses while singing the farewell song ''Takai Yama.'' The festival offers a captivating, fantastical atmosphere that contrasts with the daytime.' where id = 'r-8dIUNd0oc43BqGdBQEI';
update content_bodies set title = '飛騨高山の人気撮影スポット「赤い中橋」の桜も満開です', description = 'この動画では、飛騨高山の人気撮影スポット「赤い中橋」の桜について紹介しています。鮮やかな赤色の橋とピンク色の桜、緑色の木々のコントラストが春らしい絶景を生み出しています。' where id = 'KgvuzxjejL6ePBOTqwKCe';
update content_bodies set title = 'The Cherry Blossoms at the Popular Photography Spot ''Red Nakabashi'' in Hida Takayama are in Full Bloom', description = 'This video introduces the cherry blossoms at ''Red Nakabashi'', a popular photography spot in Hida Takayama. The vibrant red bridge contrasts beautifully with the pink cherry blossoms and the green trees, creating a picturesque spring scene.' where id = 'Z5QbSZUDX7ht1N_TVGsxe';
update content_bodies set title = '高山祭の獅子舞', description = 'この動画では、高山祭で行われる獅子舞について紹介しています。お囃子の音色に合わせて力強く舞う姿は、見る者に迫力を与えます。' where id = 'ajd14BnKiB-j0ZwOkMXTo';
update content_bodies set title = 'Takayama Festival Lion Dance', description = 'This video introduces the lion dance performed during the Takayama Festival. The powerful movements of the dancers, synchronized with the lively sounds of the accompanying music, create a captivating spectacle.' where id = 'GEcfznEjIFibxnwPYBE9G';
update content_bodies set title = '春の高山祭(山王祭)が無事に終了しました。', description = '春の高山祭(山王祭)が無事に終了したことを紹介する動画です。晴天に恵まれ、満開の桜の中で屋台の曳き揃えやからくり奉納、御巡幸、夜祭りが行われました。2日間で約18万8000人が訪れ、大変賑わった祭りとなりました。' where id = '2Ra-VRQ-1Rx_j5cWr_gx1';
update content_bodies set title = 'The Spring Takayama Festival (Sanno Festival) Successfully Concluded', description = 'The Spring Takayama Festival, also known as the Sanno Festival, has successfully concluded. The event was blessed with clear skies and full-bloom cherry blossoms, featuring various activities such as the parade of floats, karakuri performances, processions, and night festivities. Over the two days, approximately 188,000 visitors attended, making it a vibrant and lively occasion.' where id = '9wWY-q2YQE0Y-z0EpzTvg';
update content_bodies set title = '高山祭「飛騨人HIDABITO」受け継がれる伝統．技術．想い', description = 'この動画では、高山祭「飛騨人HIDABITO」について紹介しています。高山の人々の誇りや、伝統と技術がどのように受け継がれているのかを伝えています。高山祭は地域の文化を象徴する重要なイベントであり、地元の人々の意気が感じられる内容となっています。' where id = 'pPC6rLvVtDgZUjUHUR108';
update content_bodies set title = 'Takayama Festival ''HIDABITO'': A Tradition, Skill, and Spirit Passed Down', description = 'This video introduces the Takayama Festival ''HIDABITO'', showcasing the unwavering pride of Takayama and the spirit of its people.' where id = 'R-QroWIuNsOxzxf3OqRSf';
update content_bodies set title = '江名子川の桜ライトアップ', description = 'この動画では、江名子川の桜ライトアップについて紹介しています。ライトに照らされた桜が妖艶に浮かび上がり、夜のおさんぽにぴったりの季節です。川沿いに並ぶ桜や松、橋の絶景を見に出かけてみてはいかがでしょうか。' where id = 'GGZCAL-edS40wqDhBryYp';
update content_bodies set title = 'Cherry Blossom Light-Up at Enako River', description = 'This video introduces the cherry blossom light-up at Enako River, where the illuminated cherry blossoms appear enchanting. As the season for pleasant evening strolls arrives, consider taking a trip to enjoy the stunning views of cherry blossoms, pine trees, and bridges along the riverside.' where id = 'TRP5kMMHo0z7jgrSJOY9-';
update content_bodies set title = '平安時代にタイムスリップしたような、艶やかな春のおとずれをつげる「#生きびな祭」', description = 'この動画では、平安時代にタイムスリップしたような艶やかな春の訪れを告げる「#生きびな祭」について紹介しています。この祭りは飛騨一宮水無神社で行われ、養蚕や農業の繁栄、女性の幸福を祈念しています。' where id = '2RBc9eol9A6S7UQW7Kb5N';
update content_bodies set title = 'A Vibrant Spring Arrival: The ''Ikibina Festival'' Transporting You to the Heian Period', description = 'This video introduces the ''Ikibina Festival,'' which heralds the arrival of a vibrant spring reminiscent of the Heian period. The festival is held at the Hida Ichinomiya Minashi Shrine, where prayers are offered for the prosperity of sericulture and agriculture, as well as for the happiness of women.' where id = 'G_6iplcyzK68-iZ2YgYwj';
update content_bodies set title = '位山山脈から湧き出る鉱泉の「臥龍の郷」', description = 'この動画では、一之宮町に位置する標高1,529mの位山山脈から湧き出る鉱泉を源泉とする「臥龍の郷」について紹介しています。良質な温泉や露天風呂、サウナ、ジャグジー、リラクゼーションルームなど、癒しのスポットとしての魅力が詰まっています。' where id = '2psKJLXyoEPWxjrR88RwM';
update content_bodies set title = 'Garyu no Sato: A Healing Spot with Natural Hot Springs', description = 'This video introduces ''Garyu no Sato'', a healing spot located in Ichinomiya Town, which is fed by mineral springs from the 1,529m high Wuyama Mountain Range. Visitors can enjoy high-quality hot springs, open-air baths, saunas, jacuzzis, and relaxation rooms.' where id = 'bQVySQqOcWMW9s1DviHRo';
update content_bodies set title = '1000年の時を越えていまなお咲き誇る一之宮町の名所「臥龍桜」', description = 'この動画では、一之宮町の名所「臥龍桜」について紹介しています。この大樹は国指定の天然記念物で、周囲は7.3メートル、東西に20メートル、南北に30メートルの枝を広げています。ピンク色の桜花が視界一面に広がり、見る人を魅了します。' where id = '1mQbgHCNIkRQSJd1G-pTZ';
update content_bodies set title = 'The Famous ''Garyu-zakura'' in Ichinomiya Town, Blooming for 1000 Years', description = 'This video introduces ''Garyu-zakura'', a famous landmark in Ichinomiya Town. This massive cherry tree, designated as a national natural monument, has a circumference of 7.3 meters and branches extending 20 meters east-west and 30 meters north-south. The pink cherry blossoms create a stunning visual display.' where id = 'Fniu5M-U_hpMucuWTWolR';
update content_bodies set title = '江戸時代から愛される一之宮町の伝統工芸品「宮笠」', description = 'この動画では、飛騨高山の一之宮町で江戸時代から愛されている伝統工芸品「宮笠」について紹介しています。「宮笠」はイチイやヒノキの木を薄く削り、細長く切ったものを水に浸して柔らかくし、それを編み込んで作られます。' where id = 'Zi2YZzL-PDlQN7zpe62um';
update content_bodies set title = 'Traditional Craft of Miyagasa in Ichinomiya Town, Loved Since the Edo Period in Hida Takayama', description = 'This video introduces ''Miyagasa,'' a traditional craft from Ichinomiya Town in Hida Takayama, which has been cherished since the Edo period. Miyagasa is made by thinly shaving and cutting wood from trees like Ichii and Hinoki, soaking it in water to soften it, and then weaving it together.' where id = 'HlkkycYSjA9804A2VL8Fg';
update content_bodies set title = 'ReVIEW! #飛騨高山　久々野町', description = '株式会社MGNの代表取締役、桐山淳一さんが久々野町の魅力を紹介します。久々野町は高山市の南部に位置し、美しい自然が広がる地域です。この町は果物や野菜の生産が盛んで、「ひだ桃源郷」とも呼ばれています。春には果物の花が咲き誇り、夢のような風景が広がります。特に「飛騨りんご」や「飛騨もも」、「飛騨なし」、「飛騨メロン」が有名で、特に飛騨りんごを使った「アップルパイ」は人気で、すぐに完売します。また、アルコピアスキー場跡地では毎年8月にひまわり園がオープンし、約20万本のひまわりが咲き誇ります。さらに、8月中旬にはくぐの納涼夏まつりが開催され、尺玉が夜空を飾ります。ぜひ久々野町にお越しください。高山市街地から車で約30分です。' where id = '-Qxzt4av-K760EGsdHSe1';
update content_bodies set title = 'ReVIEW! #Kuguno Town, Hida Takayama', description = 'Junichi Kiriyama, CEO of MGN Co., Ltd., introduces the charms of Kuguno Town, located in the southern part of Takayama City, known for its beautiful natural scenery. This area is renowned for its fruit and vegetable production, earning the nickname ''Hida Peach Source Village.'' In spring, the blooming fruit flowers create a picturesque landscape. Notable local specialties include ''Hida apples,'' ''Hida peaches,'' ''Hida pears,'' and ''Hida melons.'' The ''Apple Pie'' made from Hida apples is particularly popular and sells out quickly. Additionally, a sunflower garden opens every August at the former Alcopia Ski Resort, featuring around 200,000 sunflowers, making it a new tourist attraction. The Kugu Summer Festival, held in mid-August, showcases spectacular fireworks that light up the night sky, creating an unforgettable experience. Visitors are encouraged to explore Kuguno Town, just a 30-minute drive from downtown Takayama.' where id = '2JeBRZvpepy_opTZLhwZd';
update content_bodies set title = '標高1,529ｍ、宮川と飛騨川の分水嶺の山「位山」', description = 'この動画では、標高1,529ｍの位山について紹介しています。位山は宮川と飛騨川の分水嶺に位置し、霊山として崇められています。周囲には樹木や植物が生い茂り、自然との出会いを楽しむことができます。登山道を歩くと、多くの巨石群が現れ、神秘的な雰囲気を醸し出しています。' where id = 'JUEgMGHS9oCl-xxFLrtt6';
update content_bodies set title = 'Mount Iizumi: A Sacred Peak at 1,529m', description = 'This video introduces Mount Iizumi, standing at an elevation of 1,529 meters, which serves as the watershed between the Miyagawa and Hida rivers. Revered as a sacred mountain, it is surrounded by lush trees and plants, offering opportunities to connect with nature. As you walk the hiking trails, you will encounter numerous giant rock formations that create a mystical atmosphere.' where id = 'JQWtmWgRM_mVutiwEgSab';
update content_bodies set title = '高山駅から車で約20分の「久々野公民館」', description = 'この動画では、高山駅から車で約20分の場所にある「久々野公民館」を紹介しています。明治から平成に作られたおひな様や土雛、江戸時代から伝わる貴重な展示物があり、飾らなくなったおひな様を集めて今では1600体以上が展示されています。' where id = 'tNENQPilhlnmLomW4e7QU';
update content_bodies set title = 'Kuzukano Community Center: A Hidden Gem Near Takayama Station', description = 'This video introduces the Kuzukano Community Center, located about 20 minutes by car from Takayama Station. The center showcases hina dolls and clay hina from the Meiji to Heisei periods, as well as valuable pieces passed down from the Edo period. It has gathered over 1,600 hina dolls that are no longer displayed.' where id = 'RkMtZixPSFYZJr_bljRBa';
update content_bodies set title = '飛騨高山 自然と歴史が調和する町 一之宮', description = '一之宮町は、田舎暮らしや地元の人々とのふれあいを体験できるグリーンツーリズムが盛んな町です。町のシンボルである臥龍桜を眺めたり、分水嶺が見える位山を散策したりすることで、自然の恵みや山里の食を楽しむことができます。また、内閣府認定のどぶろく特区で、町内の民宿やレストランで地元のどぶろくを味わえるのも魅力です。冬季にはモンデウスパークでウィンタースポーツが楽しめる白銀のゲレンデが広がります。' where id = 'wAuqDgWEUTia6OMNStzcx';
update content_bodies set title = 'Hida Takayama: A Town Harmonizing Nature and History - Ichinomiya', description = 'Ichinomiya Town is known for its vibrant green tourism, allowing visitors to experience rural life and interact with locals. The town''s symbol, the Garyu Cherry Blossom, offers a picturesque view, while the nearby Mt. Wiyama provides opportunities for hiking and enjoying the natural bounty and local cuisine. As a designated ''Doburoku Special Zone'' by the Cabinet Office, visitors can savor locally brewed doburoku at inns and restaurants throughout the town. In winter, the Mondeus Park transforms into a winter sports haven with its snowy slopes.' where id = 'q4yYfJZQlWzbZZeaMUYCd';
update content_bodies set title = '合掌造りをはじめとした飛騨の古い貴重な民家が復元され、農山村の暮らしを知ることができる「#飛騨の里」', description = 'この動画では、合掌造りを含む飛騨の古い民家が復元された「#飛騨の里」について紹介しています。ここでは、地域の市民から寄付された1000体以上の土びなを鑑賞することができ、農山村の暮らしを知る貴重な体験ができます。#飛騨高山' where id = 'g-E0BjIX4cft0y1N8sqRk';
update content_bodies set title = 'Hida no Sato: A Glimpse into Traditional Rural Life', description = 'This video introduces ''Hida no Sato,'' where valuable old houses from Hida, including the gassho-zukuri style, have been restored. Visitors can learn about rural life in the mountains and enjoy viewing over 1,000 clay hina dolls donated by local citizens.' where id = 'eyqs5HUXH_FFfm6T6_uzB';
update content_bodies set title = 'ReVIEW! 飛騨高山 奥飛騨温泉郷上宝町', description = '奥飛騨の宿、故郷の女将・中野梓さんと台湾から移住されたリャオさんが、奥飛騨温泉郷・上宝町の魅力を紹介します。上宝町は高山市の北東部に位置し、旧上宝村が高山市と合併した際に東部が奥飛騨温泉郷、西部が上宝町となりました。奥飛騨温泉郷は北アルプスの麓に広がる5つの温泉地（平湯、福地、新平湯、栃尾、新穂高）から成り、100以上の露天風呂があり、その数は日本一とされています。上宝町は標高650mの高冷地にあり、自然に恵まれた農業と林業が盛んな地域です。ぜひ奥飛騨温泉郷上宝町にお越しください。高山市街地から車で約60分、平湯バスターミナルからは約30分です。' where id = '7Uq3hbeOALjukwdxu2Gvg';
update content_bodies set title = 'ReVIEW! Okuhida Onsenkyo Kamitakara Town', description = 'Landlady Azusa Nakano of Okuhida Inn and Ms. Liao, who moved from Taiwan, introduce the charms of Okuhida Onsenkyo/Kamitakara Town, located in the northeastern part of Takayama City. The former Kamitokara Village was divided into east and west during its merger with Takayama, with the east becoming Okuhida Onsenkyo and the west Kamitakara Town. Okuhida Onsenkyo features five hot spring resorts at the foot of the Northern Alps: Hirayu, Fukuchi, Shin-Hirayu, Tochio, and Shinhotaka, boasting over 100 open-air baths, the most in Japan. Kamitakara Town, situated at an altitude of 650 meters, thrives in agriculture and forestry, nurtured by its natural surroundings. Visitors are encouraged to explore Okuhida Onsenkyo Kamitakara Town, which is about a 60-minute drive from downtown Takayama and 30 minutes from Hirayu Bus Terminal.' where id = 'TJ3QDHEW2QEgdvLmjsxfu';
update content_bodies set title = 'ReVIEW! #飛騨高山　朝日町', description = '鈴蘭高原カントリークラブの松下瑛大さん、森本翔太さん、山川ひなさんが朝日町の魅力を紹介します。朝日町は高山市の南東部に位置し、美しい自然環境が魅力の地域です。町内にはアウトドア初心者向けのキャンプ場が多く、様々なタイプのキャンプ場が美しい自然を背景に点在しています。鈴蘭高原や美女高原からは御嶽山や乗鞍岳が望め、春には水芭蕉が咲き、秋には神川でアマゴやイワナ釣りが楽しめます。冬には氷点下の森が幻想的なライトアップで彩られます。訪れた際には、道の駅ひだ朝日村で特産品の「よもぎ」を使った料理をぜひ味わってみてください。朝日町は高山市街地から車で約30分の距離にあります。' where id = 'qIpIDO5lrXh89Rc02fuzf';
update content_bodies set title = 'ReVIEW! #Hida Takayama Asahi Town', description = 'Suzuran Kogen Country Club''s Eidai Matsushita, Shota Morimoto, and Hina Yamakawa introduce the charms of Asahi Town, located in the southeastern part of Takayama City. This area is known for its beautiful natural environment and offers numerous campgrounds suitable for outdoor beginners, allowing visitors to experience nature directly. Notable locations include Suzuran Kogen and Bijo Kogen, where one can view Mt. Ontake and Mt. Norikura. In spring, skunk cabbage blooms, and fishing for amago and char is popular in the Akigami River during autumn. The winter season features a fantastical lighting display in the sub-zero forest. Visitors are encouraged to try local specialties, particularly mugwort, at the roadside station Hida Asahi Village, which offers a variety of dishes made from this spring-harvested ingredient. Asahi Town is just a 30-minute drive from downtown Takayama.' where id = '63mj6Q2c8XCucf9Ng29gR';
update content_bodies set title = 'SUNNY COAST KAYAKS　シーカヤックツーリング【ドローン撮影】観光三重', description = '伊勢神宮から車で30分の場所に位置するSUNNY COAST KAYAKSは、南伊勢町にあり、町の半分以上が伊勢志摩国立公園に含まれています。この地域は海と山の豊かな自然に恵まれており、壮大なリアス式海岸が続く五ヶ所湾で爽快なシーカヤックを楽しむことができます。初めての方でも楽しめるツーリングで、無人の浜辺を巡りながら探検気分を味わうことができます。' where id = 'k2SlTZ6ZMGUq_9is7UvLW';
update content_bodies set title = 'SUNNY COAST KAYAKS - Sea Kayaking Tours with Drone Photography in Mie', description = 'Located just 30 minutes by car from Ise Jingu, SUNNY COAST KAYAKS is situated in Minami-Ise Town, where more than half of the area is part of the Ise-Shima National Park. This region is blessed with rich natural beauty, featuring both mountains and the sea. At SUNNY COAST KAYAKS, you can enjoy refreshing sea kayaking in the stunning Gokasho Bay, known for its magnificent ria coastline. Experience the thrill of exploring uninhabited beaches on a kayaking tour that is enjoyable even for beginners.' where id = 'Q8kWMgNzP9znNdoj8HFev';
update content_bodies set title = 'ReVIEW! 飛騨高山 国府町', description = 'こくふ観光協会会長の北村家光さんが、飛騨高山の北部に位置する国府町の魅力を紹介します。この地域は歴史と自然が豊かで、千数百年前には斐陀国の政治の中心地であったと考えられています。古墳や石器時代の出土品、国宝の安国寺経蔵、清峯寺の円空仏など、多くの文化財や歴史的建造物が見られ、「日本遺産」にも指定されています。美しい山々に囲まれ、四季折々の風景が楽しめ、特に春には桜野公園の桜や桃の花が咲き誇り、「ピーチロード」として親しまれています。また、標高1,200mの水源を持つ宇津江四十八滝では、滝を巡りながらトレッキングやピクニックが楽しめます。国府町での時間は心を癒してくれることでしょう。' where id = 'WlrGlCBFZlvGFbIMSWx2L';
update content_bodies set title = 'ReVIEW! Kokufu Town, Hida Takayama', description = 'Mr. Iemitsu Kitamura, chairman of the Kokufu Tourism Association, introduces the charms of Kokufu Town, located in the northern part of Takayama City. This area is rich in history and nature, believed to have been the political center of Hidanokuni over a thousand years ago. Visitors can explore numerous cultural assets, including ancient tombs, Stone Age artifacts, the national treasure Ankoku-ji Kyozo, and the Enku Buddha at Seiho-ji Temple, all part of a designated ''Japanese Heritage Site.'' Surrounded by beautiful mountains, Kokufu Town offers seasonal scenery, particularly stunning in spring when cherry blossoms bloom in Sakurano Park and peach blossoms line the roads, known as ''Peach Road.'' The Utsue Shijuhachi Falls, with a water source at 1,200m, features many waterfalls perfect for trekking and picnicking. A visit to Kokufu Town promises to soothe the soul.' where id = 'CvQeE5h5UM0PPLci99jwG';
update content_bodies set title = 'ReVIEW! 飛騨高山 荘川町', description = '荘川観光協会会長の渡邉武志さんと旅館経営の道下智恵さんが荘川町の魅力を紹介します。荘川町は高山市の西部に位置し、中心部の標高は約800mで、日中の寒暖差は20℃以上にもなります。この気候を活かして高冷地野菜や清流の水を使ったそばが栽培されています。春には桜が咲き乱れ、特に樹齢500年の荘川桜は「キセキの桜」として地域のシンボルです。また、荘川町には飛騨地域の伝統的な家屋を見学できる荘川の里や、日本最大級の五連水車、巨大な石臼があるそばの里荘川などの魅力的なスポットがあります。訪れた際には、地元の名物「荘川そば」をぜひ味わってみてください。荘川町の自然の恵みを受けたこの蕎麦は、心と体で旅を満喫できる美味しさです。' where id = 'xWP03m6QlAPwVvnm8kaYF';
update content_bodies set title = 'ReVIEW! Shokawa Town, Hida Takayama', description = 'Takeshi Watanabe, chairman of the Shokawa Tourism Association, and Chie Michishita, an inn manager, introduce the charms of Shokawa Town, located in the western part of Takayama City at an altitude of about 800 meters. The town experiences a daily temperature difference of over 20 degrees Celsius, which supports the growth of highland vegetables and buckwheat, benefiting from the clear river water. In spring, cherry blossoms bloom beautifully, with the 500-year-old Shokawa Sakura, known as ''Kiseki no Sakura,'' being a beloved regional symbol. Shokawa Town also features attractions like Shogawa no Sato, showcasing traditional Hida houses, and Soba Sato Shogawa, home to Japan''s largest five-wheeled water wheel and a giant stone mill. Visitors are encouraged to try the local specialty, ''Shokawa Soba,'' which reflects the town''s natural bounty. A trip to Shokawa Town promises a fulfilling experience for both mind and body.' where id = 'sFCNum0ODjAiLQ6I8hmmb';
update content_bodies set title = 'かぶとの森テラス　キャンプ＆ローカルフィットネス【ドローン撮影】観光三重', description = '鈴鹿川源流に位置する「かぶとの森テラス」は、山と川に囲まれた自然豊かなキャンプ場です。ここではキャンプだけでなく、森林ヨガやサイクリングなどのアウトドアアクティビティを楽しむことができる「ローカルフィットネス」が人気です。健康に良く、心身ともにリフレッシュできる体験が提供されています。' where id = 'S3eja2Fp3EQEGs2iNXM_I';
update content_bodies set title = 'Kabutono Mori Terrace: Camping & Local Fitness [Drone Footage] Tourism Mie', description = 'Kabutono Mori Terrace is a nature-rich campsite located at the source of the Suzuka River, surrounded by mountains and rivers. In addition to camping, visitors can enjoy outdoor activities such as forest yoga and cycling, which are part of the popular ''Local Fitness'' program. This combination promotes health and provides a refreshing experience for both the mind and body.' where id = 'iSAlkMaYJZEM94TS2CJto';
update content_bodies set title = '温泉群馬「My Gunma　～私だけの群馬を探して～」', description = '群馬県は450以上の源泉を有し、様々な泉質を持つ「温泉王国」として知られています。日本有数の名湯から、一軒宿の秘湯まで、個性豊かな温泉が揃っています。自分だけの特別な温泉を探してみてください。女優の手島実優さん（前橋市在住）がこの取り組みに参加しています。群馬の温泉についてもっと知りたい方は、公式サイトをご覧ください。' where id = 'SbWkNDd9ZKmbtpVLKIVk-';
update content_bodies set title = 'My Gunma - Discovering My Unique Gunma', description = 'Gunma Prefecture is known as a ''hot spring kingdom'' with over 450 sources and various types of mineral waters. It offers a rich diversity of hot springs, from famous baths to hidden gems in solitary inns. Explore and find your own special hot spring experience. The actress Miyu Tejima, who resides in Maebashi City, has participated in this initiative. For more information about Gunma''s hot springs, visit the official site.' where id = 'GCJh1itbO7c1LkPiZPnXn';
update content_bodies set title = 'ReVIEW! 飛騨高山 高山市街地', description = '一般社団法人飛騨・高山菅コンベンション協会の藤原一也さんが、高山市の魅力を紹介します。高山市街地は歴史と文化が息づく町で、江戸時代からの歴史的な建物が多く保存されており、訪れる人々はまるで江戸時代にタイムスリップしたかのような感覚を味わえます。日本三大朝市の一つである宮川朝市と陣屋前朝市では、地元の農産物や工芸品が並び、賑やかな朝の光景が広がります。また、春と秋に行われる高山祭は、日本三大美祭の一つとして知られ、重厚な屋台や華やかな祭り装束が魅力です。この地域は日本の原風景を感じられる場所で、国際的にも有名で多くの外国人観光客が訪れます。ぜひ高山市街地にお越しください。' where id = '6uKaD1rwKMFQ3fG5uNuVk';
update content_bodies set title = 'ReVIEW! Takayama City Area', description = 'Kazuya Fujiwara from the Hida/Takayama Suga Convention Association introduces the charm of Takayama City, which is rich in history and culture. The city center features a well-preserved old townscape with numerous historic buildings from the Edo period, allowing visitors to feel as if they have stepped back in time. Notable attractions include the Miyagawa Morning Market and Jinya-mae Morning Market, both among Japan''s three major morning markets, showcasing local agricultural products and crafts in a vibrant morning atmosphere. The Takayama Festival, recognized as one of Japan''s three most beautiful festivals, takes place every spring and fall, featuring impressive floats and colorful festival costumes. This area, known for its original Japanese scenery, is popular with international tourists. Visitors are encouraged to explore the Takayama city area.' where id = '39vi3unMS9j_Y-ohYPxQJ';
update content_bodies set title = '情緒ある合掌造りが目を惹く「平湯民俗館」', description = 'この動画では、情緒ある合掌造りが特徴の「平湯民俗館」について紹介しています。館内には囲炉裏や農機具などの伝統的な展示物があり、撮影スポットとしても最適です。また、近くにある「平湯の湯」で日帰り入浴を楽しんだ後の休憩にもぴったりな場所です。' where id = 'aFpHWjvD3VJkyHuuCmt9Y';
update content_bodies set title = 'The Charming Gassho-zukuri of Hirayu Folk Museum', description = 'This video introduces the Hirayu Folk Museum, which features the charming Gassho-zukuri architecture. The museum showcases traditional items such as irori (hearths) and farming tools, making it an ideal spot for photography. After enjoying a day at the nearby Hirayu Onsen, visitors can relax at the museum, which offers a perfect break.' where id = '7HBGrQS8ZR34ANGGIUEu_';
update content_bodies set title = '御岳山と乗鞍岳を望む #飛騨高山 「高根町」', description = '飛騨高根は、明治から大正時代にかけて、貧しい飛騨から信州へと糸引き稼ぎに行く娘たちが通った野麦街道を有する自然豊かなエリアです。御岳山の北端、継子岳と乗鞍岳を望むことができ、キャンプ場も多く、秋には美しい紅葉が楽しめます。涼しい高地の環境を生かし、アスリートたちがトレーニングに訪れる地としても注目されています。また、在来の品種「火畑そば」も人気です。ぜひ、飛騨高根を訪れてみてはいかがでしょうか。' where id = 'HlMSskW7cv2D5rTlJPjnx';
update content_bodies set title = 'Mt. Ontake and Mt. Norikura View from Takane Town, Hida Takayama', description = 'Takane, located in Hida, is a rich natural area where daughters from impoverished Hida traveled along the Nomugi Pass to earn a living in distant Shinshu during the Meiji and Taisho eras. It offers stunning views of Mt. Ontake, Mt. Kegusuko, and Mt. Norikura. The region is known for its many campgrounds that take advantage of the abundant nature, and visitors can enjoy beautiful autumn foliage. The cool highland climate attracts athletes for training, and the local variety of soba, ''Hibata Soba,'' is also popular. A visit to Hida Takane is highly recommended!' where id = 'CNBkNhxispzhp3ziJu7at';
update content_bodies set title = 'ウナギ養殖から受け継ぐ絶品の秘伝タレとうな丼が人気の「#うな亭」', description = 'この動画では、ウナギ養殖から受け継がれた秘伝のタレを使用したうな丼が人気の「#うな亭」について紹介しています。奥飛騨の名水「たるま水」に2日間寝かせることで、臭みのない柔らかなウナギを味わうことができます。また、コストパフォーマンスが非常に良い点も魅力です。' where id = 'ClYW0XkvyPOIwgMEN5aq7';
update content_bodies set title = 'Popular ''Unatei'' Known for Its Secret Sauce and Unadon Passed Down from Eel Farming', description = 'This video introduces ''Unatei,'' a restaurant famous for its exquisite secret sauce and unadon, which is made from eels that have been soaked for two days in the pure water of Taruma, located in Okuhida. This process results in soft eels without any unpleasant odor. Additionally, the restaurant offers great value for money.' where id = 'yFi9oDflg9ipJx11nibEC';
update content_bodies set title = '平湯温泉にある「#アルプス街道平湯」', description = 'この動画では、平湯温泉に位置する「#アルプス街道平湯」について紹介しています。ここでは、飛騨山椒を使った唐揚げや飛騨牛まん、飛騨パイン牛乳のソフトクリーム、さるぼぼチュロスなど、テイクアウトグルメが豊富に揃っています。これらのメニューは土日祝限定で販売されています。' where id = 'jncJkBB_t61hbpDed6pb8';
update content_bodies set title = 'Alps Kaido Hirayu at Hirayu Onsen', description = 'This video introduces ''Alps Kaido Hirayu'' located in Hirayu Onsen. The establishment offers a variety of takeout gourmet options, including fried chicken made with Hida pepper, Hida beef buns, soft serve ice cream made with Hida pineapple milk, and Sarubobo churros. These items are available only on weekends and holidays.' where id = '839Px1tdYRJH5Dny5diM3';
update content_bodies set title = '全国的にも珍しい約100頭のツキノワグマに出逢えるクマのテーマパーク「#奥飛騨クマ牧場」', description = 'この動画では、全国的にも珍しい約100頭のツキノワグマに出逢えるクマのテーマパーク「#奥飛騨クマ牧場」について紹介しています。ここでは、のんびりと過ごしているクマたちや、エサをおねだりする愛嬌たっぷりの姿を見ることができ、訪れる人々は心温まる癒しのひとときを楽しむことができます。' where id = 'igNSDT9xj17t_ZZiMpfZv';
update content_bodies set title = 'A Rare Bear Theme Park with About 100 Asiatic Black Bears: #Okuhida Bear Ranch', description = 'This video introduces the #Okuhida Bear Ranch, a unique bear theme park where visitors can encounter approximately 100 Asiatic black bears. The bears are seen relaxing and playfully begging for food, providing a heartwarming and soothing experience.' where id = 'W5oGVCYSqTVsoY8MNI5iV';
update content_bodies set title = '北アルプスを一望できる絶好のロケーションが魅力の「モンデウスパーク」', description = 'この動画では、北アルプスを一望できる絶好のロケーションが魅力の「モンデウスパーク」について紹介しています。初心者から中・上級者まで楽しめる幅広いコースが用意されており、お子様にもオススメです。また、ソリ専用広場バンビーノは囲いがあるため、安全に楽しむことができます。' where id = 'refOC0T-yMji3wsokRWLL';
update content_bodies set title = 'Mondeus Park: A Great Location Overlooking the Northern Alps', description = 'This video introduces Mondeus Park, which boasts a fantastic location with a view of the Northern Alps. The park offers a wide range of courses suitable for beginners as well as intermediate and advanced skiers. It is also recommended for children, with a dedicated sledding area called Bambino that is enclosed for safety.' where id = '7hJTw8P6jkpP0ry5Wj0Cy';
update content_bodies set title = '平湯温泉にある良質かけ流しの名湯「#ひらゆの森」', description = 'この動画は平湯温泉にある良質かけ流しの名湯「#ひらゆの森」について紹介しています。豊かな自然に囲まれた情緒ある露天風呂が人気で、訪れる人々に癒しのひとときを提供しています。また、敷地内の森林の中には貸切のバレルサウナがあり、特別な「ととのう」体験ができることも魅力の一つです。' where id = 'JPrvKl-WZAZXJc-09bPRN';
update content_bodies set title = 'Hirayunomori: A High-Quality Hot Spring in Hirayu Onsen', description = 'This video introduces Hirayunomori, a renowned hot spring in Hirayu Onsen known for its high-quality flowing water. Surrounded by rich nature, it features a popular outdoor bath that offers a serene atmosphere. Additionally, visitors can experience a unique ''totonou'' moment in a private barrel sauna located within the forested area of the property.' where id = '8koEpPd-h60kKwpafeARL';
update content_bodies set title = '一之宮と久々野を結ぶ国道41号線「宮峠トンネル」', description = 'この動画では、一之宮と久々野を結ぶ国道41号線に位置する「宮峠トンネル」について紹介しています。トンネルを抜けると、一之宮の美しい田園風景が広がります。' where id = 'RU4d30h1MSQknqUwucOHX';
update content_bodies set title = 'Miyadake Tunnel on National Route 41 Connecting Ichinomiya and Kubikawa', description = 'This video introduces the Miyadake Tunnel on National Route 41, which connects Ichinomiya and Kubikawa. Upon exiting the tunnel, a beautiful rural landscape of Ichinomiya unfolds.' where id = 'lyOZlvvqolBtj9DdH2vqR';
update content_bodies set title = '飛騨高山と荘川蕎麦', description = '樹齢500年の荘川桜が見守る荘川町は、歴史と自然が交錯する場所です。山々に囲まれ、四季折々の美しい景色を楽しむことができ、桜、新緑、紅葉、雪景色が訪れる人々を魅了します。この地域では清流の水を活かした蕎麦の栽培が盛んで、東京や名古屋から高山に向かう途中の立ち寄りスポットとして最適です。荘川町はそばの花の栽培が有名で、味、香り、食感が絶品の蕎麦を地元の飲食店で楽しむことができます。' where id = '-yFZbJWxV_P0E4IyHm8RC';
update content_bodies set title = 'Hida Takayama and Shokawa Soba', description = 'Shokawa Town, watched over by the 500-year-old Shokawa cherry blossoms, is a place where history and nature intertwine. Surrounded by mountains, visitors can enjoy stunning seasonal views, including cherry blossoms, fresh greenery, autumn leaves, and snowy landscapes. The area is known for its thriving soba cultivation, utilizing the clear waters of the Shokawa River, making it a perfect stop for travelers heading to Takayama from Tokyo or Nagoya. Shokawa Town is famous for its soba flowers, offering exceptional taste, aroma, and texture that can be savored in local restaurants.' where id = 'a6lvISsNc3LS_ihRVSdDW';
update content_bodies set title = '飛騨高山 帰りたくなる郷 奥飛騨温泉郷', description = '奥飛騨温泉郷は、飛騨山脈（北アルプス）の麓に位置する歴史ある温泉地で、平湯、福地、新平湯、栃尾、新穂高の5つの温泉地から成り立っています。秘湯的な温泉地や賑やかな温泉地があり、それぞれに野趣あふれる露天風呂が設けられており、温泉巡りの楽しさを体感できます。厳しい冬を迎える奥飛騨では、雪見風呂や白銀の世界、氷のライトアップなど、幻想的な冬の絶景を楽しむことができます。ぜひお越しください。' where id = 'QZrzeHhyMcOFSVye-269N';
update content_bodies set title = 'Okuhida Onsen: A Hometown You Want to Return To', description = 'Okuhida Onsen is a historic hot spring town located at the foot of the Hida Mountains (Northern Alps), consisting of five hot spring areas: Hirayu, Fukuchi, Shin-Hirayu, Tochio, and Shinhotaka. This area features a variety of hot spring resorts, ranging from hidden gems to lively spots, each offering rustic open-air baths that provide a genuine hot spring experience. During the harsh winter, Okuhida transforms into a snowy wonderland, allowing visitors to enjoy stunning winter scenery, including snow-viewing baths, a silver world, and ice illuminations. We invite you to visit and experience this unique destination.' where id = 'N-hb0ugwmTz5Is_QiamsB';
update content_bodies set title = '夜の静寂な雰囲気の中、降り積もる雪の中にライトアップされた赤い中橋が浮かび上がり幻想的な雰囲気', description = 'この動画では、夜の静寂な雰囲気の中で降り積もる雪に包まれた赤い中橋がライトアップされている様子を紹介しています。昼間とは異なる美しい中橋の姿をお楽しみください。' where id = 'nhhHyyVJRU-XuCCR45umx';
update content_bodies set title = 'A Fantastical Scene of the Illuminated Red Nakabashi Bridge in the Snowy Night', description = 'This video showcases the red Nakabashi Bridge, beautifully illuminated against the backdrop of falling snow in a serene night atmosphere. Experience the stunning view of the bridge, which offers a different charm compared to the daytime.' where id = 'pNpbr-LglXAFbxmSc2fwZ';
update content_bodies set title = '平湯大滝の幻想的なライトアップと結氷まつり', description = 'この動画は、日本の滝百選にも選ばれている平湯大滝が幻想的にライトアップされた平湯大滝結氷まつりについて紹介しています。高さ64メートル、幅6メートルの滝水は、奥飛騨の冬の寒さにより巨大な氷柱へと変化します。' where id = '84MQCEIIIOk_PWXgLZeaM';
update content_bodies set title = 'The Enchanting Light-Up of Hirayu Falls at the Hirayu Falls Ice Festival', description = 'This video introduces the Hirayu Falls, selected as one of Japan''s top 100 waterfalls, which is beautifully illuminated during the Hirayu Falls Ice Festival. The waterfall, with a height of 64 meters and a width of 6 meters, transforms into massive ice pillars due to the cold winter temperatures of Okuhida.' where id = '1DRlxLQoHDrrAYYsDfKqg';
update content_bodies set title = '中尾かまくらまつりが昨日からスタートしました！', description = '中尾かまくらまつりが始まり、白山神社の境内には大小様々なかまくらが並んでいます。満天の星空の下、氷のキャンドルやかがり火が灯り、幻想的な雰囲気を醸し出しています。雪国ならではの美しい景色が楽しめるイベントです。' where id = '6sspg4crM1c8Al5S_mHIj';
update content_bodies set title = 'Nakao Kamakura Festival Starts Yesterday!', description = 'The Nakao Kamakura Festival has begun, featuring various sizes of kamakura (snow huts) set up in the grounds of Hakusan Shrine under a starry sky. The scene is illuminated by ice candles and bonfires, creating a magical atmosphere that showcases the breathtaking beauty unique to snowy regions.' where id = 'snraxc3nvaEli_qyjNjQx';
update content_bodies set title = '日本の美しい原風景と飛騨人の暮らしや文化を体験できる「#飛騨の里」', description = 'この動画では、飛騨人の暮らしや文化を体験できる「#飛騨の里」について紹介しています。特に冬にしか見ることができない、雪化粧した合掌造りの家々や風情ある雪景色が楽しめるスポットとして、訪れる価値があります。' where id = 'OudRF9yDdjPDKUPnLvvoh';
update content_bodies set title = 'Experience the Beautiful Original Scenery of Japan and the Life and Culture of the Hida People at ''#Hida no Sato''', description = 'This video introduces ''#Hida no Sato'', a place where you can experience the beautiful original scenery of Japan along with the life and culture of the Hida people. It showcases the charming winter landscapes, including the snow-covered gassho-zukuri houses, which can only be enjoyed during the winter season.' where id = 'f-PtttrvPv9x-95ToAWiE';
update content_bodies set title = '名古屋方面から高山に向かう東海北陸自動車道は、一面の白銀世界！', description = 'この動画では、名古屋方面から高山に向かう東海北陸自動車道の美しい雪景色を紹介しています。青空と雪のコントラストが印象的で、冬の風景が楽しめます。旅行者には、安全運転を心がけるよう呼びかけています。' where id = '7EscYZuJlJ2YvVov4WydI';
update content_bodies set title = 'The Tokai-Hokuriku Expressway from Nagoya to Takayama: A World of White!', description = 'This video introduces the stunning snowy landscape along the Tokai-Hokuriku Expressway as you travel from Nagoya to Takayama. The bright blue sky contrasts beautifully with the white snow, creating a picturesque winter scene. Travelers are advised to take care while making their journey.' where id = 'ylT74C_1g3E6fNKJjXHep';
update content_bodies set title = 'りんごや桃の産地として有名な久々野町で作られる「手作りアップルパイ」', description = 'この動画では、久々野町で作られる手作りアップルパイについて紹介しています。久々野町は美味しいリンゴや桃の産地として知られており、1本のパイには甘く煮たリンゴが4つ以上も入っており、ボリューム満点です。作る数には限りがあり、売り切れ次第終了となります。' where id = 'r8NwNLciUiygEOjO6MS9W';
update content_bodies set title = 'Homemade Apple Pie from the Famous Apple and Peach Producing Area of Kuzukano Town', description = 'This video introduces the homemade apple pie made in Kuzukano Town, known for its delicious apples and peaches. Each pie contains more than four sweetly cooked apples, making it very filling. The number of pies made is limited, and they are sold out once they are gone.' where id = 'dLOtK9LSTA8nT-09xmQal';
update content_bodies set title = '奥飛騨温泉郷の平湯温泉にある平湯の湯', description = 'この動画では、奥飛騨温泉郷の一部である平湯温泉に位置する平湯の湯について紹介しています。自然のとろりとしたやわらかい肌触りのお湯は、特に冬の時期に白銀の世界を眺めながら入ると格別な体験を提供します。' where id = '9ZmY4HB5pssL_zzdC2AQ2';
update content_bodies set title = 'Hirayu Onsen in Okuhida Onsen Village', description = 'This video introduces Hirayu no Yu, located in Hirayu Onsen, which is part of the Okuhida Onsen Village. The hot spring features soft, natural water that provides a unique bathing experience, especially during winter when visitors can enjoy the stunning snowy landscape.' where id = '-KC1EoNNo7nx7uQT1SfFF';
update content_bodies set title = '飛騨高山　氷点下の森', description = '「氷点下の森」は、幻想的な氷の世界を楽しめる冬の絶景スポットです。昭和46年から始まり、氷点下10度の自然を活かして作られたこの氷の森は、昼間はブルー、夜は青、赤、緑にライトアップされ、30年以上の人気を誇ります。美しい氷の造形は癒しの空間を提供し、特に寒い日にはシャボン玉が空中で凍る現象も見られます。毎年2月の第二土曜日には「氷点下の森 氷祭り」が開催され、ライトアップやミニコンサートなどのイベントが盛りだくさんです。2024年1月1日から2月29日まで、高山市朝日町胡桃島で開催され、駐車場も無料です。寒さ対策と滑りにくい靴での訪問をお勧めします。' where id = 'MiLxMadhF51GNDPTKpcJa';
update content_bodies set title = 'Hida Takayama: The Forest Below Freezing', description = 'The ''Forest Below Freezing'' offers a magical ice world, showcasing breathtaking winter scenery. Since 1971, this event has transformed the natural beauty of winter, with temperatures dropping to -10°C. The ice forest is illuminated in blue during the day and in vibrant colors like blue, red, and green at night, making it a popular attraction for over 30 years. The stunning ice formations create a serene atmosphere, especially on cold days when soap bubbles freeze mid-air without breaking upon landing. The ''Ice Festival'' takes place on the second Saturday of February, featuring light displays and mini-concerts, attracting large crowds. Visitors are encouraged to experience this unique winter wonderland. Event details: January 1 to February 29, 2024, at Asahi-cho Kurumi Island, Takayama. Free parking available. For inquiries, contact Hida Asahi Tourism Association.' where id = 'f0D4uKNt6d3iG_S685l-7';
update content_bodies set title = '２階建てゴンドラに乗って大パノラマの絶景を見られる「新穂高ロープウェイ」', description = 'この動画では、２階建てゴンドラに乗ることで大パノラマの絶景を楽しめる「新穂高ロープウェイ」について紹介しています。また、2024年2月12日まで「SHINHOTAKA CRYSTAL SNOW PARK」が開催中であることも触れています。' where id = '_HFT1iUyudo3faFMH7NHF';
update content_bodies set title = 'Experience Stunning Panoramas on the Two-Story Gondola at ''Shinhotaka Ropeway''', description = 'This video introduces the ''Shinhotaka Ropeway'', where visitors can enjoy breathtaking panoramic views while riding in a two-story gondola. The ''SHINHOTAKA CRYSTAL SNOW PARK'' event is currently being held until February 12, 2024.' where id = 'YriE6umPa5SDtxkzzBrqu';
update content_bodies set title = 'そば通が足しげく通う、塩で食べる蕎麦「#蕎麦正」', description = 'この動画では、そば通が頻繁に訪れる塩で食べる蕎麦「#蕎麦正」について紹介しています。店主が手打ちする蕎麦は、一口ごとに感じる風味と食感が絶品で、手打ちの芳醇な風味が一杯一杯に詰まっています。飛騨高山での必食の一品です。' where id = 'l1pgKop1sj2ziHayv40DU';
update content_bodies set title = 'Soba Lovers Frequent the Salt-Served Soba at ''#SobaMasashi''', description = 'This video introduces ''#SobaMasashi'', a place where soba enthusiasts often visit to enjoy soba served with salt. The owner handcrafts the soba, delivering an exquisite flavor and texture with every bite. The rich aroma of the handmade soba is packed into each serving, making it a must-try in Hida Takayama.' where id = 'hwgVq5EoRVLeVTZKAbeEl';
update content_bodies set title = '快晴の飛騨高山、青空に雪が映えます。', description = 'この動画では、快晴の飛騨高山の様子を紹介しています。今日は暖かく、凛とした空気が心地よく、ドライブに最適な日です。木々に積もった雪が太陽の光を受けてきらめき、青空とのコントラストが美しい景色を作り出しています。' where id = 'lXTAXieEqZs_sEl9vMVe9';
update content_bodies set title = 'Clear Skies in Hida Takayama, Snow Shines Against the Blue Sky', description = 'This video introduces the beautiful clear weather in Hida Takayama. The warm and crisp air makes for a pleasant driving experience. The snow accumulated on the trees sparkles in the sunlight, creating a stunning visual against the blue sky.' where id = 'aJ0T3WAcVrucggwiFX7II';
update content_bodies set title = '年の瀬市の開催', description = 'この動画では、陣屋前で毎朝行われている朝市が年末の期間限定で「年の瀬市」として開催される様子を紹介しています。ここでは、しめ縄や松飾りなどのお正月飾りが販売され、地元の方々が新年の準備のために訪れます。特に、木の枝に紅白のお餅を巻き付けた「花もち」などが人気です。' where id = 'WqZjQGu2HPqIDMoqVG5io';
update content_bodies set title = 'New Year''s Market at Jinya-mae', description = 'This video introduces the New Year''s Market, held at Jinya-mae every morning during the year-end period. The market features traditional New Year''s decorations such as shimekazari and matsukazari, which are considered auspicious. Local residents visit to prepare for the New Year, purchasing items like ''hanamochi,'' which consists of red and white rice cakes wrapped around tree branches.' where id = 'bJOEwmqOlTYttuh08g4a5';
update content_bodies set title = '道の駅桜の郷荘川と桜香の湯', description = 'この動画では、道の駅桜の郷荘川に隣接する桜香の湯について紹介しています。桜香の湯では、天然木材を使用した浴場や開放感のある露天風呂があり、清流「庄川」のせせらぎを聞きながら、天然温泉を楽しむことができます。' where id = '-D5YpLbEdX63Xf_eJUeQs';
update content_bodies set title = 'Sakura no Sato Sogawa Roadside Station and Sakura no Yu', description = 'This video introduces Sakura no Yu, which is adjacent to the Sakura no Sato Sogawa Roadside Station. Visitors can enjoy natural hot springs in a bathhouse made of natural wood and an open-air bath, all while listening to the soothing sounds of the Shogawa River.' where id = 'BqnnI2Gw2ew2CDQxDwSkr';
update content_bodies set title = '荘川の玄関口「道の駅桜の郷荘川」', description = 'この動画では、荘川の玄関口である「道の駅桜の郷荘川」について紹介しています。ここでは、旬の高原野菜や特産品の蕎麦、そば餅、名物のけいちゃんが販売されています。また、みたらし団子や飛騨牛めし、五平餅などのご当地グルメもおすすめです。' where id = 'yf5LRc6m7eElNNO2C5zeB';
update content_bodies set title = 'Gateway to Sōgawa: Roadside Station Sakura no Sato Sōgawa', description = 'This video introduces the Roadside Station Sakura no Sato Sōgawa, the gateway to Sōgawa. It features seasonal highland vegetables, local specialties such as soba and soba mochi, and the famous keichan. Local gourmet options like mitarashi dango, Hida beef rice, and gohei mochi are also recommended.' where id = 'bvdquaLr8G-DTJ0Hj-F5I';
update content_bodies set title = '飛騨高山の伝統的な「赤かぶ漬」', description = 'この動画では、飛騨高山で昔から人々が栽培し、作られてきた「赤かぶ漬」について紹介しています。「赤かぶ漬」は江戸時代から続く飛騨を代表する伝統の食文化であり、その作り方を映像で見ることができます。' where id = 'haYddzll6uCr9kFwrZfUv';
update content_bodies set title = 'Traditional ''Akakabu-zuke'' Pickles from Hida Takayama', description = 'This video introduces ''Akakabu-zuke'', a traditional pickled dish that has been cultivated and made by the people of Hida Takayama for generations. It represents the food culture of Hida, continuing since the Edo period.' where id = 'ztZW30N1fSalgHav1DCUk';
update content_bodies set title = '飛騨国分寺の大銀杏の木が見頃を向かえています', description = 'この動画では、飛騨国分寺の大銀杏の木が見頃を迎えている様子を紹介しています。昔から、国分寺のイチョウの葉が落ちると雪が降ると言われており、飛騨高山でも気温が下がり、冬の訪れを感じる時期となっています。' where id = '9v-bGz9VuaDXUx6oanA0i';
update content_bodies set title = 'The Great Ginkgo Tree at Hida Kokubunji is at its Peak', description = 'This video introduces the Great Ginkgo Tree at Hida Kokubunji, which is currently at its peak. It has been said for a long time that when the leaves of the ginkgo tree fall, snow will come. As the temperature drops in Hida Takayama, the arrival of winter is felt.' where id = 'SZN4kI3T3XzvJiQfDCdXH';
update content_bodies set title = '山の斜面に建つモノレール付きの伝統的な日本の温泉旅館 | 川場温泉ユトリアン', description = '川場温泉ユトリアンは、山の斜面に位置する伝統的な日本の旅館で、モノレールを利用したユニークな体験を提供しています。旅館内には、アンティーク展示室や広々とした客室、大きな公共浴場があり、訪れるゲストは日本の田園風景を楽しむことができます。宿泊には食事が含まれており、JR上越線の上毛高原駅からの無料シャトルバスでアクセス可能です。国際旅行者向けの特別プランも用意されており、料金は2名で54,000円からとなっています。この動画では、旅館の施設や周辺の景観を詳しく紹介しています。' where id = 'iQIVEnerBDQTX0D8cacsR';
update content_bodies set title = 'Traditional Japanese Onsen Ryokan with Monorail Built on a Mountain Slope | Kawaba Onsen Yutorian', description = 'Kawaba Onsen Yutorian is a traditional Japanese ryokan located on a mountain slope, offering a unique experience with a monorail. The ryokan features various amenities including antique exhibits, spacious rooms, and a large public bath. Guests can enjoy beautiful views of the Japanese countryside and a delightful dining experience with meals included in the stay. The accommodation is accessible via a free shuttle bus from JR Jomo-Kogen Station, and special plans are available for international travelers. Prices start at 54,000 yen per night for two people, including meals. The video provides a detailed tour of the ryokan, showcasing its facilities and the surrounding landscape.' where id = 'SPw9cbQ1qs6C7tPhDVeZr';
update content_bodies set title = 'ReVIEW! 飛騨高山 高山市街地', description = '一般社団法人飛騨・高山菅コンベンション協会の藤原一也さんが高山市の魅力を紹介します。高山市街地は歴史と文化が息づく町で、江戸時代からの歴史的な建物が多く保存されており、訪れる人々はまるで江戸時代にタイムスリップしたかのような感覚を味わえます。日本三大朝市の一つである宮川朝市と陣屋前朝市では、地元の農産物や工芸品が並び、賑やかな朝の光景が広がります。また、高山祭は日本三大美祭の一つとして知られ、春と秋に行われる重厚な屋台や華やかな祭り装束が魅力です。この地域は日本の原風景を感じられる場所であり、国際的にも有名で多くの外国人観光客が訪れます。ぜひ高山市街地にお越しください。' where id = 'R1boYE855bxuBxPH0CgGS';
update content_bodies set title = 'ReVIEW! Takayama City Area', description = 'Kazuya Fujiwara from the Hida/Takayama Suga Convention Association introduces the charm of Takayama City, which is rich in history and culture. The city center features a well-preserved old townscape with numerous historic buildings from the Edo period, allowing visitors to feel as if they have stepped back in time. Notable attractions include the Miyagawa Morning Market and Jinya-mae Morning Market, both among Japan''s three major morning markets, showcasing local agricultural products and crafts in a vibrant morning atmosphere. The Takayama Festival, recognized as one of Japan''s three most beautiful festivals, takes place every spring and fall, featuring impressive floats and colorful festival costumes. This area, known for its original Japanese scenery, is popular with international tourists. Visitors are encouraged to explore the Takayama city area.' where id = '3NMZmqfrJ6b1dNeeuvYAS';
update content_bodies set title = 'ReVIEW! 飛騨高山 奥飛騨温泉郷上宝町', description = '奥飛騨の宿、故郷の女将・中野梓さんと台湾から移住されたリャオさんが、奥飛騨温泉郷・上宝町の魅力を紹介します。上宝町は高山市の北東部に位置し、旧上宝村が高山市と合併した際に東部が奥飛騨温泉郷、西部が上宝町となりました。奥飛騨温泉郷は北アルプスの麓に広がる5つの温泉地（平湯、福地、新平湯、栃尾、新穂高）から成り、100以上の露天風呂があり、その数は日本一とされています。上宝町は標高650mの高冷地にあり、自然に恵まれた農業と林業が盛んな地域です。ぜひ奥飛騨温泉郷上宝町にお越しください。高山市街地から車で約60分、平湯バスターミナルからは約30分です。' where id = 'd2uCZHST9-vbYLOAY-bro';
update content_bodies set title = 'ReVIEW! Okuhida Onsenkyo Kamitakara Town', description = 'Landlady Azusa Nakano from Okuhida Inn and Ms. Liao, who moved from Taiwan, introduce the charms of Okuhida Onsenkyo/Kamitakara Town, located in the northeastern part of Takayama City. The former Kamitokara Village was divided into east and west upon merging with Takayama City, with the east becoming Okuhida Onsenkyo and the west Kamitakara Town. Okuhida Onsenkyo features five hot spring resorts at the foot of the Northern Alps: Hirayu, Fukuchi, Shin-Hirayu, Tochio, and Shinhotaka, boasting over 100 open-air baths, the most in Japan. Kamitakara Town, situated at an altitude of 650 meters, thrives in agriculture and forestry, nurtured by its natural surroundings. Visitors are encouraged to explore this beautiful area, which is about a 60-minute drive from downtown Takayama and 30 minutes from Hirayu Bus Terminal.' where id = 'PViTzd_53mwk4s64dfL_L';
update content_bodies set title = '【三重弁】[他撮り] Moment Capturer  ~It''s gonna be your Stories~', description = '三重県はネイチャーアクティビティが豊富です。里山をのんびりとサイクリングしたり、穏やかな海でシーカヤックを楽しんだり、青空の下でスカイダイビングを体験したりと、楽しみ方は無限大です。ぜひ三重県にお越しください！' where id = 'Vl3MZn5h2vyj0FmmtsIuT';
update content_bodies set title = 'Mie Dialect: Moment Capturer ~It''s gonna be your Stories~', description = 'Mie Prefecture offers a wealth of nature activities. You can enjoy leisurely cycling through the satoyama, relax with sea kayaking on calm waters, or experience the thrill of skydiving under a clear blue sky. The possibilities for enjoyment are endless. We invite you to visit!' where id = 'ESBu6FmWVEU5EpgljjXdh';
update content_bodies set title = 'ReVIEW! #飛騨高山　丹生川町', description = '千光寺の住職、大下真海さんが丹生川町の魅力を紹介します。丹生川町は高山市の北東部に位置する山岳地域で、日本百名山の一つである乗鞍岳が象徴です。標高3,000ｍの山ですが、2,702ｍの畳平までバスでアクセスできるため、子どもや女性でも気軽に山の世界を体験できます。7月から8月中旬にはバスターミナル近くに天空のお花畑が広がり、希少な高山植物を観察できます。運が良ければ天然記念物のライチョウにも出会えるかもしれません。乗鞍岳の裾野には五色ヶ原の森や、日本一高い観光鍾乳洞である飛騨大鍾乳洞など、多様な見どころがあります。丹生川町は高山市街地から車で約15分、畳平から山頂までは徒歩約90分です。' where id = '-ZNR_aa1nEk1gQOTfghlu';
update content_bodies set title = 'ReVIEW! #Hida Takayama Nyukawa Town', description = 'Chief priest Mami Oshita of Senkoji Temple introduces the charm of Nyukawa Town, a mountainous area in the northeastern part of Takayama City. The town is symbolized by Mt. Norikura, one of Japan''s 100 famous mountains. Visitors can take a bus to Tatamidaira at 2,702 meters, making it accessible for children and women to experience the mountain environment. From July to mid-August, a beautiful flower field appears near the bus terminal, showcasing rare alpine plants, and there’s a chance to see the natural monument, the grouse. Attractions include Goshikigahara Forest at the foot of Mt. Norikura, the Hida Great Limestone Cave, and the rich rural scenery of the area. Nyukawa Town offers a variety of experiences, including the legend of Hida''s hero, shrine visits, and more. It is about a 15-minute drive from downtown Takayama and a 90-minute walk from Tatamidaira to the summit of Mt. Norikura.' where id = '1aHUzj02bM8XmD_roYZqi';
update content_bodies set title = 'ReVIEW! #飛騨高山　朝日町', description = '鈴蘭高原カントリークラブの松下瑛大さん、森本翔太さん、山川ひなさんが朝日町の魅力を紹介します。朝日町は高山市の南東部に位置し、美しい自然環境が魅力の地域です。町内にはアウトドア初心者向けのキャンプ場が多く、美しい自然を背景に様々なタイプのキャンプが楽しめます。鈴蘭高原や美女高原からは御嶽山と乗鞍岳が望め、春には水芭蕉が咲き、秋には神川でアマゴやイワナ釣りが楽しめます。冬には氷点下の森が幻想的にライトアップされ、多くの人々を魅了します。訪れた際には、道の駅ひだ朝日村で特産品の「よもぎ」を使った料理をぜひ味わってみてください。朝日町は高山市街地から車で約30分の距離にあります。' where id = 'aVPyx82H71kVReMqNjEWT';
update content_bodies set title = 'ReVIEW! #Hida Takayama Asahi Town', description = 'Suzuran Kogen Country Club''s Eidai Matsushita, Shota Morimoto, and Hina Yamakawa introduce the charms of Asahi Town, located in the southeastern part of Takayama City. This area is known for its beautiful natural environment and offers numerous campgrounds suitable for outdoor beginners, allowing visitors to experience nature directly. Notable spots include Suzuran Kogen and Bijo Kogen, where one can view Mt. Ontake and Mt. Norikura. In spring, skunk cabbage blooms, and fishing for amago and char is popular in the Akigami River during autumn. Winter brings a magical lighting display in the sub-zero forest. Visitors should also try the local specialty, mugwort, at the roadside station Hida Asahi Village, which features a variety of dishes made from this spring-harvested ingredient. Asahi Town is just a 30-minute drive from downtown Takayama.' where id = '-8RgyannrM47VDgCq0RN4';
update content_bodies set title = '【三重弁】[ダイジェスト版] Moment Capturer ~It''s gonna be your Stories~', description = '三重県はネイチャーアクティビティが豊富です。里山をのんびりサイクリングしたり、穏やかな海でシーカヤックを楽しんだり、青空の下でスカイダイビングを体験したりと、楽しみ方は無限大です。ぜひ三重県にお越しください！' where id = 'zMge6AWP5Bv_gHImx0wPs';
update content_bodies set title = 'Mie Dialect: Digest Version - Moment Capturer ~It''s gonna be your Stories~', description = 'Mie Prefecture offers a wealth of nature activities. You can enjoy leisurely cycling through the satoyama, relax with sea kayaking on calm waters, or experience the thrill of skydiving under a clear blue sky. The possibilities for enjoyment are endless. We invite you to visit!' where id = 'gmx1kpTcVm6Ii3tp8sLST';
update content_bodies set title = '感じる温もり、伝わる鼓動。「距離感ゼロ」「楽しさＭＡＸ」のふれあい水族館「伊勢シーパラダイス」', description = '三重県伊勢市にある「伊勢シーパラダイス」は、海洋生物に触れることができるユニークなイベントを提供する先駆的な水族館です。近年、家族連れのレジャーとして人気を集めており、特に子供たちにとって楽しく教育的な体験を提供しています。この水族館は、他では味わえない個性的な取り組みを通じて、訪れる人々に思い出に残る体験を提供することに力を入れています。水族館の魅力は、海の生き物との距離感をゼロにし、楽しさを最大限に引き出すことにあります。' where id = '1bBQphfZxM81w6pEj3-Jc';
update content_bodies set title = 'Experience Warmth and Heartbeats at Ise Sea Paradise Aquarium', description = 'Ise Sea Paradise, located in Ise City, Mie Prefecture, is a pioneering aquarium that offers unique experiences, such as interactive events where visitors can touch marine life. This aquarium stands out in a competitive market by providing engaging and innovative attractions that emphasize close encounters with sea creatures. It has become a popular destination for families, especially those with children, looking for fun and educational outings. The aquarium''s commitment to creating memorable experiences makes it a must-visit for anyone interested in marine life.' where id = 'GAnsoE09-Bbgs0omuBflz';
update content_bodies set title = '自分たちで「つくる」「加工する」「販売する」。笑顔まで手づくりの農業公園「伊賀の里モクモク手づくりファーム」（三重県伊賀市）', description = '伊賀の里モクモク手づくりファームは、12の工房や専門店、4つのレストラン・カフェを備えた農業のテーマパークです。来園者は、自分たちで製品を作り、加工する体験を楽しむことができます。また、天然温泉や宿泊施設もあり、家族やグループでの創造的で楽しい活動に最適な場所です。' where id = 'dZWpeIuDmAxDu39y-1isE';
update content_bodies set title = 'Create, Process, and Sell: The Handmade Agricultural Park ''Iga no Sato Mokumoku Handmade Farm'' (Iga City, Mie Prefecture)', description = 'Iga no Sato Mokumoku Handmade Farm is an agricultural theme park featuring 12 workshops and specialty shops, along with four restaurants and cafes. Visitors can enjoy hands-on experiences, including making and processing their own products. The park also offers natural hot springs and accommodation facilities, making it a perfect destination for families and groups looking to engage in creative and enjoyable activities.' where id = '-plmfxJYzx_8EXeX9M4lm';
update content_bodies set title = '世界に誇る三重ブランド「松阪牛」。変わらぬ美味しさを支え続ける“こだわりと絆”。', description = '三重県のブランドの中でも特に有名な松阪牛。その美味しさは世界中で評価されており、家庭でも楽しむことができます。本記事では、松阪牛の美味しさの秘密や、こだわりについて詳しく解説します。この内容は、2020年3月4日に三重テレビで放送された番組のダイジェスト版に基づいています。フルサイズの動画もオンラインで視聴可能です。' where id = 'bz7BlpVFAPTqZii3a3AJq';
update content_bodies set title = 'Matsusaka Beef: A Proud Brand of Mie Prefecture Supported by Commitment and Bonds', description = 'Matsusaka beef is one of the most renowned brands in Mie Prefecture, celebrated for its exceptional quality. This article explores the secrets behind its delicious taste and the dedication that sustains it. The content is based on a digest version of a program aired on Mie Television on March 4, 2020. For more information, viewers can access the full video online.' where id = 'x9dVI4CJswC2pmm1C3eix';
update content_bodies set title = 'ReVIEW! 飛騨高山 国府町', description = 'こくふ観光協会会長の北村家光さんが国府町の魅力を紹介します。国府町は高山市の北部に位置し、歴史と自然が豊かな地域です。千数百年前、斐陀国の政治の中心地であったとされ、多くの文化財が残っています。古墳や石器時代の出土品、国宝の安国寺経蔵、清峯寺の円空仏などが見られ、「日本遺産」にも指定されています。美しい山々に囲まれ、四季折々の風景が楽しめ、特に春には桜野公園の桜や桃の花が美しい「ピーチロード」を形成します。また、標高1,200mの水源を持つ宇津江四十八滝では、滝を巡りながらトレッキングやピクニックが楽しめます。国府町での時間は心を癒してくれることでしょう。' where id = 'Uuppiqj0LtR6BTxzzHxgG';
update content_bodies set title = 'ReVIEW! Kokufu Town, Hida Takayama', description = 'Mr. Iemitsu Kitamura, chairman of the Kokufu Tourism Association, introduces the charms of Kokufu Town, located in the northern part of Takayama City. This area is rich in history and nature, believed to have been the political center of Hidanokuni over a thousand years ago. Visitors can explore numerous cultural assets, including ancient tombs, Stone Age artifacts, the national treasure Ankoku-ji Kyozo, and the Enku Buddha at Seiho-ji Temple, all part of a designated ''Japanese Heritage Site.'' Surrounded by beautiful mountains, Kokufu offers seasonal scenery, particularly stunning in spring when cherry blossoms bloom in Sakurano Park and peach blossoms line the roads, known as ''Peach Road.'' The Utsue Shijuhachi Falls, with a water source at 1,200m, features many waterfalls ideal for trekking and picnicking. A visit to Kokufu Town promises to soothe the soul.' where id = 'dGXErRvL6m1SmerWXMmJl';
update content_bodies set title = 'ReVIEW! #飛騨高山　久々野町', description = '飛騨舟山スノーリゾートアルコピアひまわり園の桐山淳一さんが久々野町の魅力を紹介します。久々野町は高山市の南部に位置し、美しい自然が広がる地域です。この町は果物や野菜の生産が盛んで、「ひだ桃源郷」とも呼ばれています。春には果物の花が咲き誇り、夢のような風景が広がります。特に「飛騨りんご」や「飛騨もも」、「飛騨なし」、「飛騨メロン」などが特産品として有名です。中でも、飛騨りんごを使った「アップルパイ」は人気で、すぐに完売します。また、毎年8月にはアルコピアスキー場跡地にひまわり園がオープンし、約20万本のひまわりが咲き誇ります。さらに、8月中旬にはくぐの納涼夏まつりが開催され、尺玉が夜空を飾ります。ぜひ久々野町にお越しください。高山市街地から車で約30分です。' where id = 'aVNynuNcgW9HpJCyAn-kl';
update content_bodies set title = 'ReVIEW! #Kuguno Town, Hida Takayama', description = 'Junichi Kiriyama, representative of Hida Funayama Snow Resort Alcopia Sunflower Garden, introduces the charms of Kuguno Town, located in the southern part of Takayama City. Known for its beautiful natural scenery, Kuguno is famous for its fruit and vegetable production, earning the nickname ''Hida Peach Source Village.'' In spring, the blooming fruit flowers create a picturesque landscape. Notable specialties include ''Hida apple,'' ''Hida peach,'' ''Hida pear,'' and ''Hida melon.'' The ''Apple Pie'' made from Hida apples is particularly popular and sells out quickly. Additionally, a sunflower garden opens every August at the former Alcopia Ski Resort, featuring around 200,000 sunflowers, making it a new tourist attraction. The Kugu Summer Festival, held in mid-August, showcases spectacular fireworks that light up the night sky, creating an unforgettable experience. Visitors are encouraged to explore Kuguno Town, just a 30-minute drive from downtown Takayama.' where id = 'a-_thDdNMNH-IaMB-HJ3v';
update content_bodies set title = 'ReVIEW! #飛騨高山　荘川町', description = '荘川観光協会会長の渡邉武志さんと旅館経営の道下智恵さんが荘川町の魅力を紹介します。荘川町は高山市の西部に位置し、中心部の標高は約800mで、日中の寒暖差は20℃以上にもなります。この気候を活かして高冷地野菜や清流の水を使ったそばが栽培されています。春には桜が咲き乱れ、特に樹齢500年の荘川桜は「キセキの桜」として地域のシンボルです。また、荘川町には飛騨地域の伝統的な家屋を見学できる荘川の里や、日本最大級の五連水車、巨大な石臼があるそばの里荘川などの魅力的なスポットがあります。訪れた際には、地元の名物「荘川そば」をぜひ味わってみてください。この蕎麦は荘川町の気候と清らかな庄川源流の恵みを受けた美味しさがあります。心と体で飛騨荘川の旅を満喫できるでしょう。' where id = 'O3olWJw1vme7qIc3OYLyd';
update content_bodies set title = 'ReVIEW! #Shokawa Town, Hida Takayama', description = 'Takeshi Watanabe, chairman of the Shokawa Tourism Association, and Chie Michishita, an inn manager, introduce the charms of Shokawa Town, located in the western part of Takayama City at an altitude of about 800 meters. The town experiences a daily temperature difference of over 20 degrees Celsius, which allows for the cultivation of highland vegetables and buckwheat using the clear river water. In spring, cherry blossoms bloom beautifully, with the 500-year-old Shokawa Sakura, known as the ''Kiseki no Sakura,'' being a beloved regional symbol. Shokawa Town also features attractions like Shogawa no Sato, showcasing traditional Hida houses, and Soba Sato Shogawa, home to Japan''s largest five-wheeled water wheel and a giant stone mill. Visitors are encouraged to try the local specialty, ''Shokawa Soba,'' which is known for its delicious taste derived from the area''s natural blessings. A trip to Shokawa Town promises to be a fulfilling experience for both mind and body.' where id = 'yjEWU-_L3nALekLv1UApn';
update content_bodies set title = '飛騨高山・飛騨国府の里山をサイクリングで巡る', description = '飛騨国府は日本の原風景が色濃く残る地域で、山々に囲まれ、宇津江四十八滝などの自然名所が点在しています。「Flying Peaks」では、通常の観光とは異なるサイクリングツアーを体験できます。自動車が通れない道を走りながら、森林の香りや鳥のさえずり、爽快な風を五感で楽しむことができます。地元ガイドと共に電動自転車『E-bike』で巡るため、安全に楽しめます。都会では味わえない美しい景色を駆け抜ける感動は、ここでしかできない特別な体験です。' where id = 'CWw11hNWFwljZCWNSu-YM';
update content_bodies set title = 'Cycling through the countryside and nature of Hida Kokufu', description = 'Hida Kokufu is a region where Japan''s original landscapes are preserved, surrounded by mountains and featuring natural attractions like the Utsue 48 Falls. ''Flying Peaks'' offers a unique cycling tour that differs from typical sightseeing experiences. Participants can enjoy the beauty of Hida Takayama through their senses, including the forest''s scent, birdsong, and refreshing breezes, while riding on car-free roads. The tour is conducted on electric bicycles (''E-bikes'') with a local guide who is passionate about Hida Takayama, ensuring a safe and enjoyable experience. This thrilling ride through stunning scenery is a unique adventure not found in urban areas.' where id = 'rJyoZdCknT4ALlgTPIUDf';
update content_bodies set title = '飛騨高山の国宝・安国寺', description = '安国寺は飛騨エリア唯一の国宝建造物で、1345年に室町幕府を開いた足利尊氏とその兄弟直義によって国土の平穏を願い建立されました。安国寺の経典は日本遺産の構成文化財の一つとして認識されています。特に、内部にある八角輪蔵は日本で現存する最古の回転式書架であり、明（現在の中国）から入手した元版大蔵経（2000帖以上）を収蔵しています。八角輪蔵を回転させながら仏を念じると、一切経を読んだのと同じご利益が得られるとされており、ここでしか見ることができない貴重な文化財です。' where id = 'wkBwwtWg1pERRkUcMKuCt';
update content_bodies set title = 'Ankokuji Temple: A National Treasure in Hida Takayama', description = 'Ankokuji Temple is the only national treasure building in the Hida region, established in 1345 by Takauji Ashikaga and his brother Tadayoshi to pray for peace in the country. The temple''s scriptures are recognized as part of Japan Heritage. Notably, the octagonal rinzo inside is the oldest existing rotating bookshelf in Japan, housing the original version of the Tripitaka, which includes over 2,000 chapters obtained from the Ming Dynasty. It is believed that rotating the Octagonal Rinzo while contemplating the Buddha grants the same benefits as reading all the sutras. This unique cultural property is a must-see for visitors.' where id = 'KlGODtjZKXXq1Tc0KEzo1';
update content_bodies set title = '飛騨高山 せせらぎ街道 ドライブ', description = '郡上市八幡町から高山市清見町三日町を結ぶ「飛騨美濃せせらぎ街道」は、夏の新緑や秋の紅葉といった美しい季節の景色を楽しめるドライブルートです。道沿いには西ウレ峠やおおくら滝遊歩道など、自然を満喫できる遊歩道が整備されており、気軽に散策が可能です。また、道中には五平餅や雰囲気の良いカフェが点在しており、立ち寄りながらのドライブがオススメです。これからの季節は、爽やかな風を感じながら美しい山々と森林の絶景を楽しむことができます。' where id = 'Vb8fUnr_0vvCnxCOuRTnp';
update content_bodies set title = 'Hida-Mino Seseragi Kaido Drive', description = 'The Hida-Mino Seseragi Kaido connects Yahata-cho in Gujo City to Mikkamachi in Kiyomi-cho, Takayama City. This scenic driving route offers beautiful seasonal views, featuring fresh greenery in summer and vibrant autumn leaves in fall. Along the way, there are promenades like Nishiure Pass and Okura Falls Promenade, perfect for enjoying nature with easy walking access. Travelers can also stop at local attractions such as Gohei Mochi and charming cafes scattered throughout the route. As the seasons change, visitors can experience breathtaking views of mountains and forests while enjoying a refreshing breeze.' where id = 'uhU2xp5lmCbtLU2pM6OKI';
update content_bodies set title = 'おいしい日本。岡山のベスト（7分版）', description = 'この動画は岡山のベストについて紹介しています。' where id = 'B42brhigIn5XEsmaMisZZ';
update content_bodies set title = 'Yummy Japan. Okayama’s Best (7 minutes version)', description = 'This video introduces the best of Okayama.' where id = 'q8wns3hRcFPcIQeonpqt8';
update content_bodies set title = '飛騨高山 桜山風鈴まつり 2023', description = '飛騨高山の新しい夏の風物詩である「桜山風鈴まつり」が、秋の高山祭で有名な「櫻山八幡宮」で開催中です。開催期間は2023年7月22日から8月26日までで、絵馬殿には約2,000個の風鈴が飾られ、手水舎には生花が浮かび、涼しげな雰囲気を醸し出しています。毎週土曜日の夜にはライトアップや風鈴の絵付け体験イベントも行われ、夏休みの旅行にぴったりです。イベントの詳細は、岐阜県高山市桜町178で、問い合わせは0577-36-1011、また高山駅から徒歩約20分です。' where id = 'TQN0n_ePL2XcUT2m-575g';
update content_bodies set title = 'Hida Takayama Sakurayama Wind Chime Festival 2023', description = 'The Sakurayama Wind Chime Festival is a new summer tradition in Hida Takayama, taking place at the famous Sakurayama Hachiman Shrine, known for the Takayama Autumn Festival. The festival runs until August 26, featuring around 2,000 wind chimes displayed in the Ema Hall and fresh flowers floating in the water basin, creating a refreshing atmosphere. Every Saturday night (excluding the final day), there are illumination events and wind chime painting experiences, making it a perfect summer vacation destination. Event details: Sakurayama Wind Chime Festival 2023, July 22 - August 26, 2023. Illumination on August 5, 12, and 19 from 6:00 PM to 9:00 PM. Location: 178 Sakuramachi, Takayama City, Gifu Prefecture. Contact: 0577-36-1011. Approximately a 20-minute walk from Takayama Station.' where id = 'zyteXUZMynbY0N7ch5GJR';
update content_bodies set title = '桜山風鈴まつり', description = '桜山八幡宮の絵馬殿に2,000個の風鈴が飾られる「桜山風鈴まつり」。風鈴の音色を楽しみながら、厄除けの祈願を行うことができます。' where id = 'D8nLlx-7FYCEN9k86ZAeU';
update content_bodies set title = 'Sakurayama Wind Chime Festival', description = 'The Sakurayama Wind Chime Festival features 2,000 wind chimes displayed at the Ema Hall of Sakurayama Hachiman Shrine. Visitors can enjoy the soothing sounds of the wind chimes while also praying for protection from misfortune.' where id = 'lD3S8EcK9WKRfAc1FF9fs';
update content_bodies set title = '雪の城下町高山を歩く（2023年1月撮影）', description = '美しい雪景色が広がる飛騨高山の町を撮影しました。' where id = 'q93QVIczyvI-XKx2xYB9B';
update content_bodies set title = 'Walking in the Snowy Castle Town of Takayama (Photographed in January 2023)', description = 'This captures the beautiful snowy scenery of Takayama in the Hida region.' where id = 'Z06gmM_Qt7iWql4f3vEC4';
update content_bodies set title = '春の高山祭 夜祭', description = '6年ぶりに行われた14日夜の夜祭は、昼とは異なる幻想的な雰囲気が魅力です。各屋台は約100個の提灯を灯しながら町をゆっくりと巡ります。順道場を過ぎると、屋台はそれぞれの屋台蔵へ帰る際に「高い山」という曳き別れ歌を歌います。' where id = 'RsWRKXHcMSdHg5aoVO47E';
update content_bodies set title = 'Spring Takayama Festival Night Festival', description = 'The night festival held on the 14th, after a six-year hiatus, offers a magical atmosphere distinct from the daytime events. Each float, adorned with approximately 100 lanterns, slowly parades through the town. As they pass the Jun-do Hall, the floats return to their respective storage houses while singing the traditional farewell song ''Takayama.''' where id = 'iTk7mez1ig9RcjVDZdcB3';
update content_bodies set title = '春の高山祭2023 からくり奉納（14日・午後3時〜）', description = '春の高山祭では、屋台組「三番叟」「龍神台」「石橋台」の3台によるからくり奉納が行われます。伝統を受け継ぐ綱方たちが人形に息を吹き込み、見事な早変わりや華麗な演舞を披露します。' where id = 'buaexYvd2MlBvQZapbc5U';
update content_bodies set title = 'Spring Takayama Festival 2023 Karakuri Performance (14th, 3 PM)', description = 'The Spring Takayama Festival features a Karakuri performance by three floats: Sanbansou, Ryujindai, and Ishibashidai. The traditional craftsmen breathe life into the puppets, showcasing impressive quick changes and splendid dances.' where id = 'MocQEoVI6Hv97FIgfd7ZR';
update content_bodies set title = '2023年春の #高山祭 (#山王祭) 屋台編', description = '2023年4月14日と15日に開催された春の高山祭（山王祭）は、4年ぶりの本格的な祭りとなりました。2日間で約16万8000人が訪れ、賑わいを見せました。この祭りはユネスコ無形文化遺産に登録されている「高山祭の屋台行事」を特徴としており、豪華な屋台には飛騨の匠の技が光ります。屋台が動く様子を楽しむことができます。' where id = 'uX2L5le09zeR0JGOAmxhH';
update content_bodies set title = '2023 Takayama Spring Festival (Sanno Festival) Yatai Edition', description = 'The Takayama Spring Festival, also known as the Sanno Festival, took place on April 14 and 15, 2023, marking the first full-scale celebration in four years. Approximately 168,000 visitors attended over the two days, creating a vibrant atmosphere. The festival features the ''Yatai'' float events, which are registered as UNESCO Intangible Cultural Heritage. The magnificent floats showcase the exquisite craftsmanship of Hida artisans. Enjoy the dynamic movement of the floats!' where id = 'tKh1e5P2GQkvQkyZczP8f';
update content_bodies set title = '春の高山祭', description = '春の高山祭（山王祭）は、日枝神社の例祭として毎年4月14日と15日に開催されます。秋の高山祭と共に日本三大美祭の一つに数えられ、「高山祭の屋台行事」はユネスコの無形文化遺産に登録されています。青空の下、華やかな屋台が並び、多くの訪問者を魅了します。夜祭では、約100個の提灯が灯された屋台が町をゆっくりと巡り、お囃子の音色が響き渡ります。' where id = 'agPTUORifF26l1MnrVbtC';
update content_bodies set title = 'Spring Takayama Festival', description = 'The Spring Takayama Festival, also known as the Sanno Festival, is held annually on April 14th and 15th as a celebration of Hie Shrine. It is recognized as one of Japan''s three great festivals alongside the Autumn Takayama Festival, and the ''Takayama Festival Floats'' are registered as a UNESCO Intangible Cultural Heritage. Under the clear blue sky, splendid and luxurious floats attract many visitors. During the night festival, around 100 lanterns illuminate each float as they leisurely parade through the town, accompanied by the sounds of traditional music.' where id = 'f5L6291qs-zpEC3MCr8jW';
update content_bodies set title = '聖武天皇の勅願によって建立された「#飛騨国分寺」', description = 'この動画では、聖武天皇の勅願によって建立された「#飛騨国分寺」について紹介しています。特に、樹齢1250年以上とされる大イチョウが見頃を迎えており、その美しさが楽しめる時期となっています。飛騨国分寺は歴史的な背景を持つ寺院であり、訪れる人々にとって貴重な文化財となっています。' where id = 'eycfSe30UNSg6h78LZfH9';
update content_bodies set title = 'Hida Kokubun-ji Temple Established by Emperor Shomu''s Imperial Decree', description = 'This video introduces Hida Kokubun-ji Temple, which was established by the imperial decree of Emperor Shomu. The temple features a large ginkgo tree that is said to be over 1,250 years old and is currently in its prime viewing season.' where id = 'C9P60utkMEp1in4TygAyK';
update content_bodies set title = '天下の名城 高山城 ⑥大手道、金森将監屋敷(2023.1.13変更)', description = '天生14年（1586年）に飛騨国主となった金森長近公が築城した高山城の姿を、現在の町並みから探る内容です。案内人は、飛騨地域の歴史研究や発掘調査に長年携わり、高山市史編纂専門員を務める田中彰さんです。高山城は、古い町並みや遺構とともに、山城としての魅力を持っています。' where id = 'uh0EK-z2yYoTdD1hySjuy';
update content_bodies set title = 'Takayama Castle: The Famous Castle of the Land - Otemichi and Kanamori Shokan Residence (Updated on January 13, 2023)', description = 'In 1586, Kanamori Nagachika became the lord of Hida Province and constructed Takayama Castle. This exploration looks at the castle''s presence in the current townscape. The guide is Akira Tanaka, who has been involved in historical research and excavation in the Hida region for many years and serves as a specialist in compiling the history of Takayama City.' where id = 'zte4-vzO9gljnupz9F6N3';
update content_bodies set title = '天下の名城 高山城 ③二之丸', description = '天生14年（1586年）に飛騨国主となった金森長近公が築城した高山城の姿を、現在の町並みから探ります。案内人は、飛騨地域の歴史研究や発掘調査に長年携わり、高山市史編纂専門員を務めた田中彰さんです。高山城は、古い町並みや遺構とともに、山城としての魅力を持っています。' where id = '2tNT79iBtk_TT2b6CaTcV';
update content_bodies set title = 'Takayama Castle: The Famous Castle of the Land - Ninomaru', description = 'In 1586, Kanamori Nagachika became the lord of Hida Province and constructed Takayama Castle. This exploration looks at the castle''s presence in the current townscape. The guide is Akira Tanaka, who has been involved in historical research and excavation in the Hida region for many years and serves as a specialist in compiling the history of Takayama City.' where id = 'D8orK3uY3Va5KXiufKlSZ';
update content_bodies set title = '飛騨高山 四十八滝 ライトアップ 期間限定開催', description = '岐阜県の宇津江四十八滝は、日本の自然100選や名水50選に選ばれたスポットです。ここには大小13の滝があり、豊かな自然の中で滝の音を楽しみながら散策できるリフレッシュスポットです。特に平滝、函滝、上段滝がライトアップされ、昼間とは異なる幻想的な雰囲気を醸し出します。ライトアップは11月6日までの期間限定で、日没から21時まで楽しむことができます。' where id = 'jvutNCOSsmuCAASOx7ilD';
update content_bodies set title = 'Limited Time Event: Light Up at Shijuhachitaki', description = 'The Shijuhachitaki Falls, located in Gifu Prefecture, is recognized as one of Japan''s top 100 natural sites and one of the 50 selected water sources. This refreshing spot features 13 waterfalls along a scenic valley, where visitors can enjoy the soothing sounds of water while exploring the rich natural surroundings. The illuminated waterfalls, including Hiradaki, Hakodaki, and Jodandaki, create a mystical atmosphere that contrasts with the daytime scenery. The light-up event is available until November 6th, from sunset until 9 PM.' where id = 'XiAtcr3vQ6Z70r-W2Zv-h';
update content_bodies set title = '飛騨高山 四十八滝 ライトアップ 期間限定開催', description = '岐阜県の名水50選や日本の自然100選に選ばれた宇津江四十八滝で、神秘的な雰囲気の「四十八滝ライトアップ」が開催されます。渓谷沿いには13の滝があり、豊かな自然の中で滝の音を楽しみながら散策できるリフレッシュスポットです。ライトアップされるのは平滝、函滝、上段滝の3つで、昼間とは異なる幻想的な景色が広がります。開催は11月6日までで、日没から21時までの限定です。' where id = 'I1eWN9Aje7qwkyk7uHK4P';
update content_bodies set title = 'Limited Time Event: Light Up at Shijuhattaki', description = 'The Shijuhattaki Light Up event offers a mystical atmosphere at the Utsue Shijuhattaki, selected as one of Japan''s top 100 natural sites and one of Gifu Prefecture''s 50 famous water sources. This refreshing spot features 13 waterfalls along a valley, where visitors can enjoy the soothing sounds of water while exploring the rich natural surroundings. The illuminated waterfalls, including Hiradaki, Hakodaki, and Jodandaki, create a fantastical scene that contrasts with the daytime ambiance. The event runs until November 6, from sunset until 9 PM.' where id = 'dvjuXjU-5C8XLJkXc3OdC';
update content_bodies set title = '伊賀忍者の里にある老舗のお茶屋「むらい萬香園」（三重県伊賀市）', description = '「むらい萬香園」は、伊賀忍者の里に位置する老舗のお茶屋で、国内外から多くのニッチなファンが訪れる観光スポットです。この穴場的な場所では、伊賀流忍者と伊賀茶の文化を発信しており、訪れる人々に独自の体験を提供しています。リンクされた動画は、2020年2月18日に放送された三重テレビの番組のダイジェスト版で、茶屋の魅力や文化的な重要性を紹介しています。' where id = 'k3Wp2ebP6FMFJDaZrZYOI';
update content_bodies set title = 'Murai Bankoen: A Long-Established Tea Shop in Iga Ninja Village (Iga City, Mie Prefecture)', description = 'Murai Bankoen is a long-established tea shop located in Iga Ninja Village, attracting numerous niche fans from both Japan and abroad. This hidden gem promotes the culture of Iga-style ninjas and Iga tea, making it a unique tourist spot. The video linked is a digest from a Mie TV program aired on February 18, 2020, showcasing the tea shop''s offerings and its cultural significance.' where id = 'Yc3gQaGBt0KTYB-kbuozt';
update content_bodies set title = '飛騨高山 秋の高山祭 2022', description = '秋の高山祭（八幡祭）は、櫻山八幡宮の例祭で、毎年10月9日・10日に開催されます。新型コロナウイルスの影響で中止が続いていましたが、2022年には3年ぶりに開催されました。残念ながら雨模様のため、御神幸や宵祭は中止となりましたが、からくり奉納は無事に行われ、多くの人々で賑わいました。高山祭は豪華絢爛な屋台や精巧な動きが魅力のからくり人形が特徴で、ぜひその様子をご覧ください。' where id = 'n-X-xbfLMvoZ1cIKVcZTw';
update content_bodies set title = 'Hida Takayama Autumn Festival 2022', description = 'The Autumn Takayama Festival, also known as the Hachiman Festival, is held annually on October 9th and 10th at Sakurayama Hachiman Shrine. After being canceled for three consecutive years due to the COVID-19 pandemic, the festival returned in 2022. Unfortunately, due to rainy weather, the procession and evening festival were canceled, but the karakuri puppet performances took place successfully, attracting many visitors. The festival is known for its splendid floats and intricately moving karakuri dolls, which are a highlight of the event.' where id = 'HKS-qB--hgcfJx067X9Y_';
update content_bodies set title = '天下の名城 高山城 ①中橋から空町', description = '天生14年（1586年）、飛騨国主となった金森長近公が築城した高山城の姿を、現在の町並みから探ります。案内人は、飛騨地域の歴史研究や発掘調査に長年携わり、高山市史編纂専門員を務めた田中彰さんです。高山城は、古い町並みや遺構とともに、地域の歴史を物語る重要な存在です。' where id = '7gc0V7OmbiLXaZB7LqdHG';
update content_bodies set title = 'The Famous Castle Takayama ① From Nakabashi to Soramachi', description = 'In 1586, Kanamori Nagachika became the lord of Hida Province and built Takayama Castle. This exploration looks at the castle''s presence in the current townscape. The guide is Akira Tanaka, who has been involved in historical research and excavation in the Hida region for many years and serves as a specialist in compiling the history of Takayama City.' where id = 'hnNldQURbYrsiVr2s_QuV';
update content_bodies set title = '秋の高山祭2022 からくり奉納（9日・正午〜）', description = 'この動画は、2022年の秋の高山祭におけるからくり奉納について紹介しています。' where id = 'AcrY65jbSEDVspevZRQt9';
update content_bodies set title = 'Autumn Takayama Festival 2022 Karakuri Offering (9th, Noon)', description = 'This video introduces the Karakuri offering at the Autumn Takayama Festival 2022.' where id = '_DXqoF3Qj_uZGfy350273';
update content_bodies set title = '飛騨高山 おおくら滝', description = '清見町を南北に貫通する飛騨せせらぎ街道は、自然の息吹を感じる快適なドライブルートです。この街道沿いに位置する「森林公園おおくら滝」では、ミズナラやブナの天然生林が広がっています。川のせせらぎを聞きながらの森林浴は、都会では味わえないリフレッシュスポットです。高さ約30ｍのおおくら滝を中心に、大小さまざまな滝を眺めながらの散策が楽しめます。' where id = '-RA1w1vm4VmgtURrm6W1R';
update content_bodies set title = 'Ohkura Falls in Hida Takayama', description = 'The Hida Seseragi Road is a pleasant driving route that runs north-south through the center of Kiyomi Town, allowing visitors to experience the beauty of nature. Located along this road is the Ohkura Falls Forest Park, where visitors can see natural forests of Mizunara and beech trees. The sound of the flowing river enhances the experience of forest bathing, providing a refreshing escape from urban life. The park features the approximately 30-meter-high Ohkura Falls, along with various other waterfalls, making it a great spot for leisurely walks and exploration.' where id = 'izrtjlgCxaTwI6cpQE4EF';
update content_bodies set title = '乗鞍スカイラインを電動自転車でサイクリング', description = '乗鞍スカイラインは、平湯峠と乗鞍岳畳平を結ぶ延長14.4キロメートルの山岳観光道路です。乗鞍岳のバスターミナルは標高2702ｍで、日本一の高さを誇ります。この絶景ロードは自転車でも登ることができ、平湯バスターミナルから徒歩2分の「モビリティステーション奥飛騨」で電動アシスト自転車をレンタルできます。神秘的な山間を走り抜け、ひんやりとした空気を感じながら登るサイクリングは格別です。ゴールまでのラスト5キロは標高2400ｍ以上で、空気も薄くなり、ダイナミックな九十九折りの道が続きます。バスでは味わえない乗鞍の空気と絶景を楽しみながら、乗鞍畳平を目指してみてはいかがでしょうか。' where id = 'a6WIMMHEB_aoeHpCDaCre';
update content_bodies set title = 'Cycling the Norikura Skyline on an Electric Bicycle', description = 'The Norikura Skyline is a scenic mountain road that stretches 14.4 kilometers, connecting the Hirayu Pass and the Norikura Mountain Tatamidaira. The bus terminal at Norikura Mountain is at an elevation of 2,702 meters, making it the highest bus-accessible point in Japan. This stunning road can be cycled as well, offering breathtaking views. You can rent an electric assist bicycle at the ''Mobility Station Okuhida,'' just a two-minute walk from the Hirayu bus terminal. As you ride through the mystical mountain scenery, you can feel the cool air and enjoy the exhilarating experience. The last five kilometers to the goal are above 2,400 meters, where the air becomes thinner, and the road features dynamic and grand switchbacks. Experience the unique atmosphere and stunning views of Norikura as you aim for Tatamidaira, an adventure that cannot be experienced by bus.' where id = 'u9FX9oOAHXc4bk06bxeyd';
update content_bodies set title = '飛騨高山の郷土料理　赤かぶ漬け', description = '「赤かぶ漬」は、飛騨高山で昔から栽培されてきた伝統的な食文化で、江戸時代から続いています。厳しい冬の寒さの中で新鮮な野菜が育たないため、地元の人々は冬に漬物を食べることを好みます。高山の大きな温度差により、ここで育つかぶは甘く、ジューシーで旨味が豊かです。塩で漬け込まれた赤かぶは、乳酸発酵によって旨味とわずかな酸味が特徴です。収穫された赤かぶは外皮が赤いですが、内部は基本的に白いため、地元の人々は色を赤く染めて、飛騨の名物である赤かぶ漬けを完成させます。' where id = 'NznhtSF2-KkYU17w7TKU4';
update content_bodies set title = 'Hida Takayama''s Local Cuisine: Red Turnip Pickles', description = 'Red turnip pickles, known as ''Akakabu-zuke'', have been cultivated and made by the people of Hida Takayama for generations. This traditional food culture, which dates back to the Edo period, showcases the region''s unique agricultural practices. The video captures the process of making these pickles, highlighting the sweet and juicy turnips that thrive in Takayama''s cold climate. The red turnips are fermented with salt, resulting in a dish that is rich in umami and has a slight acidity. The outer skin is red, while the inside is white, and locals dye the turnips to achieve the vibrant red color that characterizes this beloved dish.' where id = 'HAcfn69gc6dH0quSiNxqk';
update content_bodies set title = '2022年春の高山祭　山王祭', description = '春の高山祭（山王祭）は、旧高山城下町南半分の氏神である日枝神社の例祭で、毎年4月14日と15日に開催されます。この祭りの起源は飛騨の領国大名金森氏の時代にさかのぼり、1718年頃に屋台が登場したとされています。祭りでは、巧妙なからくり人形や仕掛けが施された戻し車など、匠の技が披露されます。2022年の春の高山祭は雨模様でしたが、雨が止んだ合間に屋台が蔵から出て、古い町並みを通る様子が見られました。' where id = 'U-YL-YUKEIQv_mds-EF-w';
update content_bodies set title = '2022 Spring Takayama Festival - Sanno Festival', description = 'The Spring Takayama Festival, also known as the Sanno Festival, is an annual event held on April 14 and 15, celebrating the deity of Hie Shrine, which is the guardian of the southern half of the old Takayama castle town. The festival''s origins date back to the era of the Kanamori clan, a feudal lord of Hida, with the first floats appearing around 1718. The festival showcases intricate karakuri puppets and mechanisms, highlighting the craftsmanship of the artisans. Although the 2022 festival experienced rainy weather, the floats were able to parade through the historic streets during brief breaks in the rain.' where id = 'VUltnRW91qo3n3hWE9uuv';
update content_bodies set title = '両面宿儺が生まれた町: 飛騨高山', description = '飛騨高山は、歴史ある町並みと四季折々の美しい風景で知られています。この地には、1600年頃に両面宿儺が現れたと言われています。飛騨千光寺は、1600年の時を超えて今も存在し、過去と現在をつなぐ重要な場所となっています。' where id = 'q4RAJJeYx1oqQQV7lXBhX';
update content_bodies set title = 'The Town Where Ryomen Sukuna Was Born: Hida Takayama', description = 'Hida Takayama is a historic town known for its beautiful seasonal landscapes. It is said that Ryomen Sukuna appeared here over 400 years ago, around the year 1600. The town features the Hida Senkoji Temple, which has stood the test of time since then, connecting the past with the present.' where id = '07nDhg1M_ckBcPrAGV6gr';
update content_bodies set title = '匠の国 飛騨高山', description = '飛騨高山には、匠の技が今も息づいています。木材の特性を理解し、漆を巧みに扱い、土や石を生活に活かす技術が受け継がれ、やがて「匠」と呼ばれるようになりました。これらの技は、今日でも継承され、磨かれ続けています。' where id = 'h72hw392LL3RGXm5YbGu1';
update content_bodies set title = 'The Land of Craftsmen: Hida Takayama', description = 'Hida Takayama is a place where the skills of craftsmen continue to thrive. The knowledge of wood, the manipulation of lacquer, and the use of soil and stone in daily life have been passed down as ''techniques'' and have eventually come to be known as ''craftsmanship.'' These skills are still being inherited and refined today.' where id = '_1wt3jVHSVY84GyY00hSx';
update content_bodies set title = '老田酒造店', description = '老田酒造店は、高山市上三之町67に位置する酒造店です。代表銘柄は「鬼ころし」で、地元の特産品として知られています。詳細については、公式ウェブサイト http://www.onikorosi.com/ をご覧ください。' where id = 'zQNsNY-fZ4KHZUzrAGukJ';
