update content_bodies set title = '教育旅行in越前和紙の里', description = 'この動画は越前和紙の里での教育旅行について紹介しています。越前和紙の里は、伝統的な和紙作りの技術を学ぶことができる場所であり、訪れる人々はその文化や歴史に触れることができます。教育旅行を通じて、学生たちは和紙の製造過程を体験し、地域の伝統を理解する貴重な機会を得ることができます。' where id = '5xQTxoUUThPFi_vSea8c5';
update content_bodies set title = 'Educational Trip in Echizen Washi Village', description = 'This video introduces the educational trip in Echizen Washi Village.' where id = 'U8pFIcRk69oPxgMrfIJBv';
update content_bodies set title = '【ＪＲ北上線　Ｔｈｅローカルな旅】 ゆだ高原駅→ほっとゆだ駅のナレーション付き車窓動画（上り方面）', description = 'この動画は、ゆだ高原駅から北上駅までの上り区間を紹介しています。車窓からの風景や沿線の観光情報を、岩手めんこいテレビのアナウンサーで西和賀町出身の高橋礼子さんがナレーションで解説しています。ローカル線ならではの魅力を感じることができる内容です。' where id = 'DQeUefneKbw2Qbu2TFwLj';
update content_bodies set title = 'JR Kitakami Line: The Local Journey - Narrated Video from Yuda Kogen Station to Hotto Yuda Station (Upward Direction)', description = 'This video showcases the upward section from Yuda Kogen Station to Kitakami Station, featuring scenic views from the train window and local tourist information narrated by Reiko Takahashi, an announcer from Iwate Menkoi Television and a native of Nishi Waga Town. Experience the unique charm of this local line.' where id = 'gWKsV8xOkVnP-dqBIZk3v';
update content_bodies set title = '飛騨高山 7蔵のん兵衛まつり 2021', description = '飛騨高山・7蔵のん兵衛まつりは、2月8日から2月28日までの開催を予定していましたが、緊急事態宣言が3月7日まで延長されたため、今年度の開催を中止することになりました。新型コロナウイルス感染症の拡大防止のための措置です。楽しみにしていた皆様には大変残念なお知らせとなりますが、次回の開催をお待ちいただけますようお願い申し上げます。何卒ご理解のほどよろしくお願いいたします。' where id = 'UPAzgKtoZ6vCIdZ7sYgOI';
update content_bodies set title = 'Hida Takayama 7 Brewery Sake Festival 2021', description = 'The Hida Takayama 7 Brewery Sake Festival, originally scheduled to take place from February 8 to February 28, has been canceled due to the extension of the state of emergency until March 7. This decision was made to prevent the spread of COVID-19. We sincerely apologize to those who were looking forward to the festival and ask for your understanding as we look forward to the next event.' where id = 'edXuWq338-EHA2fh6-DEq';
update content_bodies set title = '【ＪＲ北上線　Ｔｈｅローカルな旅】 北上駅→柳原駅のナレーション付き車窓動画（下り方面）', description = '北上駅からゆだ高原駅までの下り区間を紹介する動画です。岩手めんこいテレビの高橋礼子アナウンサーが、車窓から見える風景や沿線の観光情報をナレーションで解説します。ローカル線ならではの魅力を感じることができる内容となっています。' where id = 'ecFXip5ZFO65pwdML1hdp';
update content_bodies set title = 'The Local Journey on JR Kitakami Line: Narrated Video from Kitakami Station to Yanagihara Station (Downward)', description = 'This video features a narrated journey from Kitakami Station to Yuda Kogen Station, heading towards Yokote. The scenery visible from the train window and local tourist information are presented by Reiko Takahashi, an announcer from Iwate Menkoi Television and a native of Nishiwaga Town. Experience the unique charm of this local line.' where id = 'XC2k9fC8_zR3YYxUuvWx2';
update content_bodies set title = '【ＪＲ北上線　Ｔｈｅローカルな旅】 柳原駅→江釣子駅のナレーション付き車窓動画（下り方面）', description = 'この動画は、北上駅からゆだ高原駅までの下り区間を紹介しています。横手方面に向かう列車の車窓から見える風景や沿線の観光情報を、岩手めんこいテレビのアナウンサーで西和賀町出身の高橋礼子さんがナレーションで紹介しています。ローカル線ならではの魅力を感じることができる内容です。' where id = 'OnoYrFgaOaie1dNsWC_f1';
