update content_bodies set title = '長岡市 攝田屋・宮内地區 觀光宣傳視頻（繁體中文版）', description = '長岡市の攝田屋と宮内地区を紹介する観光宣伝動画です。この動画では、地域の魅力や観光スポットを紹介し、訪れる人々にその魅力を伝えています。' where id = 'Wx0XceYbqyfWPh99tdY3b';
