update content_bodies set title = '関西再発見の旅！「THE EXCITING KANSAI」', description = '関西は、日本を代表する世界遺産や悠久の歴史に裏打ちされた伝統・文化が息づく地域です。ここには、まだ知られていない魅力がたくさんあります。そんな魅力を探る楽しい旅に出かけてみませんか？' where id = 'MKTI_9xCNGBiX3YBNzREa';
