update content_bodies set title = '松井酒造', description = 'この動画は松井酒造(MATSUI SAKE BREWING Co.,LTD.)について紹介しています。松井酒造は日本の伝統的な酒造りを行っている企業であり、品質の高い日本酒を製造しています。' where id = 'jpNTgCN_ng8OVyBJ7AZUP';
