update content_bodies set title = '月桂冠(GEKKEIKAN OKURA SAKE MUSEUM)', description = 'この動画は月桂冠(GEKKEIKAN OKURA SAKE MUSEUM)について紹介しています。月桂冠は日本の伝統的な酒造りを体験できる場所であり、訪れる人々に日本酒の歴史や製造過程を学ぶ機会を提供しています。' where id = 'ea4lDhlRIrG0B1LoZb1Or';
update content_bodies set title = 'Gekkeikan Okura Sake Museum', description = 'This video introduces the Gekkeikan Okura Sake Museum, showcasing its significance and offerings.' where id = 'GdWWaZAsBn5a_1p_Muu1Q';
update content_bodies set title = '大阪酒ツアー', description = 'この動画では、大阪の酒文化のユニークな側面を紹介する大阪酒ツアーについて説明しています。' where id = '8fB2u7xzM28f88-3GKf6P';
