update content_bodies set title = '淡路島と徳島、日本の誕生の神話と海への架け橋', description = '関西は、日本の精神性と文化を深く広く体験できる場所です。1800年以上前の古代文明から、修験道や禅、京都を代表する華やかな平安貴族文化、さらには城や武士道、忍者に至るまで、関西は日本文化の全ての側面が集まる場所です。' where id = '1Tv2SvwZH_H4_is1glY6D';
update content_bodies set title = 'AWAJI ISLAND and TOKUSHIMA, A myth of the birth of Japan and bridge to the sea', description = 'Kansai is a region rich in Japanese spirituality and culture, offering a deep exploration of its historical and cultural heritage. With roots tracing back over 1,800 years, Kansai showcases a variety of cultural elements, including Shugendo, Zen, and the opulent Heian aristocratic culture epitomized by Kyoto. Additionally, it features significant historical sites such as castles, and embodies the traditions of bushido and ninja, making it a comprehensive representation of Japanese culture.' where id = 'eap_wayxBCFhak-DlSWKK';
update content_bodies set title = '山陰海岸、海岸の美しさと優雅さ', description = '関西は、日本の精神性と文化を深く広く体験できる場所です。1800年以上前の古代文明から、修験道や禅、京都を代表する華やかな平安貴族文化、さらには城や武士道、忍者に至るまで、関西は日本文化の全ての側面を網羅しています。' where id = '-H3jwd5dTbuCbhMJjeLTY';
