update content_bodies set title = 'BIWAKO LAKE and HOKURIKU, Living with a spring', description = 'Kansai is a region rich in Japanese spirituality and culture, offering a deep exploration of its historical and cultural heritage. With a civilization that dates back over 1,800 years, Kansai showcases various cultural elements, including Shugendo, Zen, and the elegant Heian aristocratic culture epitomized by Kyoto. The region is also home to castles, the samurai code of bushido, and the intriguing world of ninjas, making it a comprehensive representation of Japanese culture.' where id = 'ckAOegPxPiy-evPxJCoVy';
