update content_bodies set title = '播磨、姫路城と海の道', description = '関西は、日本の精神性と文化を深く広く体験できる場所です。1800年以上前の古代文明から、修験道や禅、京都を代表する華やかな平安貴族文化、さらには城や武士道、忍者に至るまで、関西は日本文化の全ての側面が集まる場所です。' where id = 'Wz9z1PnFAZFcKXPuIQTRj';
update content_bodies set title = 'HARIMA, Himeji Castle and Sea Road', description = 'Kansai is a region where one can deeply and broadly explore Japanese spirituality and culture. It encompasses a rich history that dates back over 1,800 years, showcasing various cultural elements such as Shugendo, Zen, and the opulent Heian aristocratic culture epitomized by Kyoto. Additionally, Kansai is home to significant historical features like castles, the samurai code of bushido, and the mystique of ninjas, making it a comprehensive representation of Japanese cultural heritage.' where id = 'NTRDmSC7V_kEel56P1MDP';
update content_bodies set title = '紀伊半島、熊野古道、日本の精神的起源への巡礼', description = '関西は、日本の精神性と文化を深く広く体験できる場所です。1800年以上前の古代文明から、修験道や禅、京都を代表する華やかな平安貴族文化、さらには城や武士道、忍者に至るまで、関西は日本文化の全ての側面を網羅しています。' where id = 'Qp3jLPt1d0sGHw-Ac-i2m';
update content_bodies set title = 'Kii peninsula, KUMANO KODO, Pilgrimage to Japan''s Spiritual Origins', description = 'Kansai is a region rich in Japanese spirituality and culture, offering a deep exploration of its historical roots. With a civilization dating back over 1,800 years, Kansai showcases various cultural elements, including Shugendo, Zen, and the elegant Heian aristocratic culture epitomized by Kyoto. Additionally, it features significant historical sites such as castles, the samurai code of bushido, and the mystique of ninjas, making it a comprehensive representation of Japan''s cultural heritage.' where id = 'JrZMFO1jS8uT0oafOMeq9';
update content_bodies set title = 'スピリチュアル関西、温泉', description = '関西、日本の地で千年以上にわたり受け継がれてきた文化の恵みを体全体で感じることができます。温泉、郷土料理、日本酒は、日常生活の疲れから解放され、心と体をリフレッシュさせるエネルギーを提供します。火山活動と純粋な地下水に恵まれたこの地域では、温泉文化と伝統的な旅館が楽しめます。自然の温かい湯と穏やかな環境、そして日本の伝統的なホスピタリティが融合し、心と体のスピリチュアルな解放をもたらします。清らかな伏流水から醸された日本酒を味わい、郷土料理を楽しむことで、関西は真の癒しの地となります。' where id = 'RF6oK1PkR_ttr7Wmtg2PR';
update content_bodies set title = 'Spiritual KANSAI, Onsen', description = 'Experience the enduring blessings of a culture that has thrived for over a thousand years in Kansai, Japan. This region is renowned for its hot springs (onsen), local cuisine, and Japanese sake, all of which offer a profound release from the stresses of daily life. The natural hot waters and serene surroundings, combined with traditional Japanese hospitality, create a rejuvenating experience for both body and mind. Visitors can immerse themselves in the tranquil atmosphere of ryokan (traditional inns) and enjoy the healing properties of the mineral-rich waters. Savoring local dishes alongside fine sake enhances the spiritual journey, making Kansai a true sanctuary for relaxation and revitalization.' where id = '6lAoy0Vl_yJcgXI8PRLet';
update content_bodies set title = 'スピリチュアル関西 4K ダイジェスト', description = '関西地域は、日本のスピリチュアルなメッカとして描かれ、社会の変化にもかかわらず「いのち」の本質が続いていることが強調されています。この動画では、寺院や神社、自然の名所など、さまざまな重要な場所が紹介され、地域のホスピタリティとスピリチュアルな旅が強調されています。関西を自己発見の道として探求することを促し、自然と存在の関係を示しています。また、旅が個人的な洞察や自分の世界における位置を理解する手助けになることを提案しています。' where id = 'WyDHgFzUOU-v_yWXARKND';
update content_bodies set title = 'Spiritual KANSAI 4K, digest', description = 'The KANSAI region in Japan is depicted as a spiritual Mecca, where the essence of life continues despite societal changes. The video highlights various significant locations, including temples, shrines, and natural sites, emphasizing the region''s hospitality and spiritual journey. It invites viewers to explore KANSAI as a path to self-discovery and understanding of life''s meaning, showcasing the connection between nature and existence. The content encourages reflection on how different beings interact with life, suggesting that travel can lead to personal insights and a deeper understanding of one''s place in the world.' where id = 'IYBlixPabq36cdX3GLZNL';
update content_bodies set title = 'KANSAI、日本のEXPO AUTO RIDE & GUIDEを体験する', description = 'この動画では、KANSAIにおけるEXPO AUTO RIDE & GUIDEについて紹介しています。' where id = 'ShT7X5mskGAh8vF_XhTIt';
update content_bodies set title = 'Experience KANSAI, Japan: EXPO AUTO RIDE & GUIDE', description = 'This video introduces the EXPO AUTO RIDE & GUIDE in KANSAI, Japan.' where id = 'EJOmxYYazbdePG3P8He_f';
update content_bodies set title = '志摩マリンランド　ドクターフィッシュ', description = '志摩マリンランドでドクターフィッシュの体験をしました。この体験に関する取材記事は、志摩マリンランドの公式サイトで確認できます。' where id = 'IAqGBDmiQbrAjyesWyW3H';
update content_bodies set title = 'Doctor Fish Experience at Shima Marine Land', description = 'I had the opportunity to experience Doctor Fish at Shima Marine Land. For more details, you can read the article covering this experience.' where id = 'G87GDvjwL4ebo9DBvOLGp';
update content_bodies set title = 'ビン玉ロード（三重県志摩市）｜三重県大好き"兎の助"動画｜【公式】観光三重', description = '三重県の応援キャラクター「兎の助」が紹介する動画シリーズです。夕暮れ時に浜島の旅館街から続くビン玉ロードがライトアップされ、散歩する人々の道しるべや癒しのスポットとして親しまれています。' where id = 'M_RHGUSHSGEi9QU6FeUPn';
update content_bodies set title = 'Bin Tama Road (Shima City, Mie Prefecture) | Mie Prefecture''s Favorite Character ''Usanosuke'' Video | Official Tourism Mie', description = 'This video series features ''Usanosuke'', the rabbit ninja and mascot of Mie Prefecture. The Bin Tama Road, illuminated during sunset, extends from the ryokan district of Hamajima in Shima City, serving as a guide for walkers and a soothing spot for relaxation.' where id = '9SuXF0O5ZeiRgdYShjGHh';
update content_bodies set title = '滝を浴びる豪快アドベンチャー！飛雪の滝キャンプ場の滝ダッキー（三重県紀宝町）', description = '「飛雪の滝」の滝つぼで「ダッキー」に乗る体験ができます。ダッキーは空気で膨らますカヌーで、安定性が高く初心者や小学生でも安心して楽しめます。滝に打たれたり、ダッキーの上で立ったり寝転んだりと、さまざまな遊び方が可能です。このユニークなアドベンチャーは、美しい自然の中で忘れられない体験を提供します。' where id = 'K1j6RC8hFKljj0B4iAVb3';
update content_bodies set title = 'A Thrilling Adventure Under the Waterfall! Hisetsu Falls Campground''s Duckie Experience (Kihō, Mie Prefecture)', description = 'Experience the excitement of riding a ''Duckie'' at the base of Hisetsu Falls! A Duckie is an inflatable canoe known for its stability, making it safe for beginners and children. You can enjoy various activities such as getting splashed by the waterfall, standing, or lying down on the Duckie. This unique adventure promises an unforgettable experience amidst the stunning natural scenery.' where id = '7mCveITQnSwRjRDGNfrpZ';
update content_bodies set title = 'しろんご祭（三重県鳥羽市）｜三重県大好き"兎の助"動画｜【公式】観光三重', description = '三重県鳥羽市で行われるしろんご祭は、海女の祭典です。ホラ貝の合図で、磯着姿の海女たちが海に潜り、初めてのあわびを競い合います。最初に採れたあわびは神社に供えられ、豊漁と海上安全を祈願します。この祭りは、三重県を応援するキャラクター「兎の助」が紹介する動画シリーズの一部です。' where id = 'XElMpAoukR388DCloTnXx';
update content_bodies set title = 'Shirongo Festival (Toba City, Mie Prefecture) | Mie Prefecture''s Favorite Character ''Usanosuke'' Video | Official Mie Tourism', description = 'The Shirongo Festival is a traditional event in Toba City, Mie Prefecture, celebrated by ama divers. The festival begins with a conch shell signal, prompting the ama divers, dressed in traditional attire, to dive into the sea and compete to catch the first abalone of the season. The first abalone caught is offered at a shrine as a prayer for a bountiful catch and safe navigation at sea. This event is part of a video series featuring Usanosuke, the official mascot supporting Mie Prefecture.' where id = 'Q-R-Ke4-s8TsYFTiqqGrq';
update content_bodies set title = '【公式】観光三重 のライブ ストリーム', description = 'この動画は、観光三重のライブストリームについて紹介しています。観光三重は、三重県の魅力を伝えるための公式なプラットフォームであり、視聴者にリアルタイムで情報を提供します。' where id = '3I1ZNMkOVOCKnKK6H_WtW';
update content_bodies set title = 'Official Live Stream of Mie Tourism', description = 'This video introduces the live stream of Mie Tourism.' where id = 'BfraZJY-b-hsmdZ57kjjB';
update content_bodies set title = '見栄サミット 第四話「とめどないLOVE／北勢」 #三重の観光PR動画', description = '三重県の5つのエリアを国と想定し、首脳たちが自国の自慢話で見栄を張り合うショートムービー「見栄サミット」の第四話は「とめどないLOVE／北勢」編です。このエピソードでは、北勢エリアの観光スポットが紹介されています。動画に登場する観光地の詳細は、リンク先の記事で確認できます。また、三重県観光連盟の公式サイトでは、観光、旅行、イベント、宿泊予約に関する情報が豊富に提供されています。' where id = 'C9dF4XGb_A-TlL7fBFJAc';
update content_bodies set title = 'Mie Summit Episode 4: Endless LOVE / Hokusei #Mie Tourism PR Video', description = 'The fourth episode of the short movie series ''Mie Summit'' imagines the five areas of Mie Prefecture as individual countries, where the leaders gather to boast about their regions. This episode, titled ''Endless LOVE / Hokusei,'' showcases various tourist attractions in the Hokusei area. For detailed information about the featured spots, visit the provided article link. The official Mie tourism website offers a wealth of resources for travel, events, and accommodations in Mie Prefecture.' where id = 'Kde2CXVxhUEV-DUULi94m';
update content_bodies set title = 'スピリチュアル関西、侘び寂び', description = '関西の美しい日本庭園を訪れ、正式な着物を着てお茶を点てる体験ができます。また、今も残る素朴な古民家の村を訪れることも可能です。シンプルなものの中に秩序と敬意を見出し、古いものの中に純粋な美を感じる瞬間が「侘び寂び」を体現します。古き良き日本の雰囲気が漂う関西では、伝統、静けさ、誠実さ、純粋さ、自然への敬意が感じられます。侘び寂びの美しさを体験できるこの地域は、日本の精神的な場所です。' where id = 'qNqeq2-5gudHeX7fwjyme';
update content_bodies set title = 'Spiritual KANSAI, Wabi Sabi', description = 'Experience the serene beauty of Kansai, Japan, where traditional aesthetics come to life. Visitors can explore beautiful Japanese gardens, don formal kimonos, and engage in tea preparation. The region is characterized by its old and simple homes, embodying the essence of ''wabi-sabi''—finding beauty in imperfection and simplicity. Kansai offers a harmonious atmosphere filled with respect for nature and one another, reflecting values of tranquility, honesty, and purity. This spiritual region allows one to truly appreciate the traditional Japanese ideals of simplicity and the beauty of the aged.' where id = 'OPn70rysauMrrABLYdTJI';
update content_bodies set title = 'スピリチュアル関西、心', description = '独自の感謝の表現や伝統芸能を自らの目で見ることで、世代を超えて受け継がれてきた情熱や精神的な強さ、歴史の重みを感じることができます。関西は日本の豊かで独特な文化の発祥地として知られ、地域の人々の理想、習慣、信念を体現しています。このスピリチュアルな地域では、祭りや伝統芸能、生活様式など、文化の有形無形の側面が祝われています。先人たちへの祈りや地域の恵みへの感謝を通じて、日本の永続的な文化遺産と深く結びつくことができる場所です。' where id = 'uECvnfUydNaW5-R0b_DiG';
update content_bodies set title = 'Spiritual KANSAI, Kokoro', description = 'Experiencing the unique Japanese expressions of gratitude and traditional arts firsthand allows one to appreciate the passion, resilience, and historical significance that have been passed down through generations. Kansai is recognized as the birthplace of Japan''s rich and distinctive culture, embodying the collective ideals, customs, and beliefs of its people. This spiritual region celebrates both tangible and intangible aspects of culture, including festivals, traditional performances, and ways of life. It is a place where one can connect with the prayers of ancestors and express gratitude for local blessings, making it a profound encounter with Japan''s enduring cultural heritage.' where id = 'REPqiqtjblEq2JCF-k-Wy';
update content_bodies set title = 'スピリチュアル関西、武士道', description = '伝統的な日本の武道を体験し、目の前で黒smithが魂を込めて鋼を打つ様子を見て、火花が飛び散る中で輝く剣が形作られるのを感じてください。そして、美しい城の天守閣に登り、純粋で誠実な生き方を学びましょう。武士道の哲学は、仁（人の情）、義（誠実さ）、礼（思いやり）、智（物事の本質を見極めること）、信（信じる強さ）、忠（愛する者への真心）を重視し、関西地域に根付いています。自らの道徳心を見つめ直すことで、人はより高い次元へと昇華することができます。関西は単なる地理的な場所ではなく、日本文化と価値観の本質に繋がるスピリチュアルな旅を象徴しています。' where id = 'vYoqiS_obqhcCPSgzv3gj';
update content_bodies set title = 'Spiritual KANSAI, Bushido', description = 'Experience traditional Japanese martial arts as a blacksmith forges a sword before your eyes, embodying the spirit of craftsmanship. Climb a majestic castle keep and learn the values of living a pure and honest life. The philosophy of Bushido, which emphasizes humanity, honesty, gratitude, wisdom, belief, and loyalty, is deeply rooted in the Kansai region of Japan. By reflecting on our moral compass, we can elevate ourselves to a higher level of existence. Kansai is not just a geographical area; it represents a spiritual journey that connects individuals to the essence of Japanese culture and values.' where id = '7SOyvppzcttK_0SbmAe2D';
update content_bodies set title = 'スピリチュアル関西、瞑想', description = '美しい庭と豊かな歴史に囲まれた大きな寺院で、特別な座り方を採用し、筆を持って日本の紙に心の内を表現する禅の瞑想を体験します。瞑想の後には、自然の恵みを感じる美味しい食事を楽しむことができます。この旅を通じて、日本の精神文化を学びながら、心と体の完璧なバランスを再発見します。世俗から離れ、自然と一体となることの意味を探求し、感覚を研ぎ澄ませ、自分自身を再発見する関西、日本のスピリチュアルな地域での体験です。' where id = '5rjJZ0FCUXfuRTfhA3b_o';
update content_bodies set title = 'Spiritual KANSAI, Meditation', description = 'Experience Zen meditation in a serene temple surrounded by a beautiful garden and rich history. In this tranquil setting, adopt a special seating position, hold a writing brush, and express your inner thoughts on Japanese paper. After meditation, enjoy a delicious meal that embodies the blessings of nature. This journey allows you to explore Japan''s spiritual culture while finding a harmonious balance between body and mind. Discover what it means to detach from worldly concerns and connect with nature, awakening your senses and rediscovering your true self in Kansai, Japan''s spiritual region.' where id = 'H5WdmtG-TF5zMhrs4-hr7';
update content_bodies set title = 'スピリチュアル関西、巡礼', description = 'スピリチュアル関西の全ルートを歩くことで、自然との調和を見出し、先人たちへの新たな敬意を感じることができます。この旅は内面的な探求を促し、新しい価値観や生まれ変わりの感覚をもたらします。苔むした古道は、先人たちの祈りの声を感じながら、精神的な目覚めを体験するように誘います。日本の関西にあるこれらの神聖な道を歩むことで、あなたはこの一生の中で新たな自分に生まれ変わるかもしれません。' where id = 'E4WWHvg26-WFs7OyPgZvw';
update content_bodies set title = 'Spiritual KANSAI, Pilgrimage', description = 'Walking the entire route of Spiritual KANSAI offers a profound connection with nature and a deeper appreciation for those who have walked before. This journey allows for introspection, leading to the discovery of new values and a sense of rebirth within the natural world. The ancient, moss-covered paths invite pilgrims to experience a spiritual awakening, echoing the prayers of ancestors. As you traverse these sacred trails in Kansai, Japan, you may find yourself transformed, feeling a renewed sense of self during this lifetime.' where id = 'zOljEpqZaeybIlraHwlCS';
update content_bodies set title = '真の日本、関西【4K】短編', description = '関西地域は1500年以上の歴史を誇り、多くの国宝が存在します。手つかずの自然景観と、洗練された和食文化が魅力です。訪れる人々は、真の日本を見て、感じ、味わい、体験することができます。この素晴らしい地域で、日本の美しさと文化にどっぷり浸かり、再会の日を心待ちにすることができるのです。' where id = 'gJxMk28YqQmBq3R8ikE4O';
update content_bodies set title = 'The real Japan, KANSAI【 4K 】short version', description = 'The Kansai region of Japan boasts over 1,500 years of rich history and is home to numerous National Treasures. It features untouched natural landscapes and offers an exquisite Japanese food culture. Visitors are invited to see, feel, taste, and live the true essence of Japan in this remarkable area. Kansai is a place where one can fully immerse themselves in the beauty and culture of Japan, eagerly anticipating the day of reunion with this enchanting region.' where id = '0Kpj48pY2QPf81Rci5VUS';
update content_bodies set title = '【4K】美しい景色 - ロングバージョン、関西、日本', description = 'この動画では、日本の関西地域の素晴らしい景色を紹介しています。関西についての詳細は、公式ガイドウェブサイトを訪れることで知ることができます。また、関西の最新情報や美しいビジュアルを得るために、FacebookやInstagramでもフォローできます。' where id = '-oFSluoz95MQlBOfRu-mY';
update content_bodies set title = 'Stunning Views - Long Version, KANSAI, Japan', description = 'This video showcases the breathtaking views of the KANSAI region in Japan. For more information about KANSAI, you can visit the official guide website. Additionally, you can follow KANSAI on Facebook and Instagram for updates and more stunning visuals.' where id = 'S0jdfL0Df-P0gQS2qBtas';
update content_bodies set title = '夢の地域、関西日本【 4K 】', description = '夢を持つことは非常に重要であり、それは前進するための原動力となります。より良い時期が訪れるのを待ちながら、私たちは再会できる日を夢見て、オンラインで夢を描くことが奨励されています。日本の関西地域は、未来の出会いへの希望と期待を象徴する場所として描かれ、私たちの生活における夢の重要性が強調されています。' where id = 'R6iU0mA5dBva-wj_A_AcM';
update content_bodies set title = 'The dream region, KANSAI Japan【 4K 】', description = 'Having a dream is crucial as it serves as motivation to move forward and prepare for better times ahead. Until we can reunite, we are encouraged to dream online about the beautiful Kansai region of Japan. This area is depicted as a place of hope and anticipation for future encounters, emphasizing the importance of dreams in our lives.' where id = 'rYMfYq2I4DtnM607Y0Hp2';
update content_bodies set title = '本物の日本、関西【4K】', description = '関西地域は、1500年以上の歴史を持つ日本の古都であり、数多くの国宝や文化遺産が残っています。ここには日本最古の巡礼路があり、伝統的な芸能や祭りも受け継がれています。四季折々の美しい自然景観が広がり、和食文化や精進料理も楽しめます。この動画は、関西の本物の日本を見て、感じて、味わい、体験することを促しています。関西での素晴らしい旅が待っています。' where id = 'kfhu1DBbK-IzcQ8IiMwAr';
update content_bodies set title = 'The real Japan, KANSAI【 4K 】', description = 'The Kansai region, with its rich history as the ancient capital of Japan, attracts millions of travelers. This area is home to numerous National Treasures and Cultural Assets, including Japan''s oldest pilgrimage route. Visitors can experience traditional performing arts, vibrant festivals, and breathtaking natural scenery that changes with the seasons. Kansai is also renowned for its exquisite food culture, featuring traditional Shojin cuisine, a form of Buddhist temple food. The video invites viewers to see, feel, taste, and live the essence of Japan in the Kansai region, promising an unforgettable journey.' where id = 'WB4yEA4yrt0JkPRXh-FXH';
update content_bodies set title = '旅行仿若一趟朝聖巡礼', description = '日本における旅行は、まるで一つの朝聖の旅のようです。朝聖の道を歩むことで、真の自分を取り戻し、自然と一体となり、夢を探求することができます。関西地域は、この旅のインスピレーションを与える舞台となり、旅行者に夢をオンラインで楽しむことを促し、再会の日を心待ちにさせます。' where id = 'jFQZ1Qt1HVZ31kHjPM-_r';
update content_bodies set title = 'Travel is a pilgrimage, KANSAI Japan【 4K 】', description = 'Traveling in Japan is likened to a pilgrimage, where the journey allows individuals to reconnect with their true selves. The pilgrimage roads in Japan offer a chance to harmonize with nature and explore personal dreams. The Kansai region serves as an inspiring backdrop for this journey, inviting travelers to enjoy their dreams online and look forward to a future reunion.' where id = 'JXGl8d_8w5HSavymIUNv4';
