update content_bodies set title = '関西、日本を体験する：奈良の相撲体験', description = '奈良県で提供される素晴らしい相撲体験をお楽しみください。関西地域でしか味わえないユニークな体験です。スタッフのビデオブログを通じて関西旅行の計画についての情報を得たり、提供されたリンクから関西の観光名所についてさらに学んだりできます。' where id = 'dlQC3KK_7EhvaCNGddSol';
update content_bodies set title = 'Experience KANSAI, Japan: Sumo Experience, Nara', description = 'Discover an amazing Sumo Experience in Nara Prefecture, a unique offering in the Kansai region. For more insights, check out the staff''s video blog on Kansai Travel Planning and learn more about the attractions in KANSAI through the provided link.' where id = 'vtuLhL-9-k6GTQq4I5f1k';
update content_bodies set title = '関西を体験する：大阪・難波の壷一茶', description = 'このエントリーでは、堺にある壷一茶の本店と、難波のスカイOにある店舗を訪れる様子が紹介されています。また、関西旅行の計画に関するスタッフのビデオブログも含まれており、地域の魅力についての洞察が得られます。' where id = 'lgaavg9zs1mUutHY7RLSo';
update content_bodies set title = 'Experience KANSAI, Japan: Namba Tsuboichi Tea, Osaka', description = 'This entry highlights a visit to Tsuboichi Tea, showcasing their main shop in Sakai and their location in Sky O, Namba. It also includes a staff video blog related to Kansai travel planning, providing insights into the region''s offerings.' where id = 'Qbt0DQdkyE3mLXrxyKkp_';
update content_bodies set title = '関西、日本を体験する：姫路喧嘩祭り', description = '姫路喧嘩祭りは、関西の姫路市で10月に開催される祭りです。このユニークなイベントでは、伝統的な戦いの儀式や文化的なパフォーマンスが披露され、地元の活気ある文化を体験したい訪問者を惹きつけます。スタッフのビデオブログや、提供されたリンクを通じてこの地域についてさらに知ることができます。' where id = 'g4Vnko6bQMQlJO47a1HuL';
update content_bodies set title = 'Experience KANSAI, Japan: Himeji Kenka Matsuri', description = 'The Himeji Kenka Matsuri, or Fighting Festival, takes place in October in Himeji, Kansai. This unique event showcases traditional fighting rituals and cultural performances, attracting visitors who want to experience the vibrant local culture. For more insights, check out the staff''s video blog on Kansai travel planning and learn more about the region through the provided links.' where id = '4xI3T8LN03FbwsTvV4PcE';
update content_bodies set title = '異なる視点で見る - 寺院にて -', description = 'この動画は、日本を訪れる外国人観光客が日本の文化、習慣、行動、社会的規範を理解することを促進し、ストレスや不安、混乱といった障壁を軽減することを目的としています。また、日本の住民が基本的なマナーを再考し、ホスピタリティの精神を育むことも目指しています。お互いの視点を意識し、周囲への配慮を持つことが重要であると伝えています。' where id = 'ryQiKL4InFILRETMeKYJL';
update content_bodies set title = 'Seeing differently - in the temple -', description = 'This video aims to reduce stress and barriers such as anxiety and confusion for foreign tourists visiting Japan by promoting an understanding of Japanese culture, customs, and social norms. It also encourages Japanese residents to reflect on basic manners and foster a spirit of hospitality. The goal is to enhance mutual understanding and consideration for different perspectives, creating a more harmonious environment for both visitors and locals.' where id = '3n0EZ8ZotlX1gLPOEBdH7';
update content_bodies set title = '志摩マリンランド　大回遊水槽の海女さん', description = '志摩マリンランドに関する取材記事で、大回遊水槽での海女さんの活動に焦点を当てています。海女さんは、独自の潜水技術を持つ伝統的な女性ダイバーであり、地域文化への貢献が評価されています。記事では、彼女たちの日常活動や海洋環境における役割の重要性についての洞察が提供されています。' where id = '7hnM_j1wH_HagPSookFzR';
update content_bodies set title = 'Shima Marineland: Ama Divers in the Large Swimming Tank', description = 'This article covers the Shima Marineland, focusing on the ama divers who perform in the large swimming tank. The ama divers are traditional female divers known for their unique diving techniques and contributions to the local culture. The article provides insights into their daily activities and the significance of their role in the marine environment.' where id = 'rXHgZCvqnDiyHI2_sAwFT';
update content_bodies set title = '市場での異なる視点', description = 'この動画は、日本を訪れる外国人観光客が直面するストレスや不安、混乱を軽減することを目的としています。日本の文化や習慣、行動、社会的規範を理解することを促し、また日本の住民に対しては基本的なマナーを再考し、ホスピタリティの精神を育むことを目指しています。お互いの視点を意識し、周囲への配慮を持つことが重要であると伝えています。' where id = 'kscmG8Pl-oIxbN17pkmpU';
update content_bodies set title = 'Seeing differently - at the market -', description = 'This video addresses the challenges faced by foreign tourists in Japan, such as anxiety and confusion, by promoting an understanding of Japanese culture, customs, and social norms. It also encourages Japanese residents to reflect on basic manners and the spirit of hospitality. The goal is to foster mutual understanding and awareness of different perspectives, enhancing the experience for both visitors and locals.' where id = 'anpW83bwCEgUZ10ZTD6vY';
update content_bodies set title = '異なる視点で見る - 街の中で -', description = 'この動画は、日本を訪れる外国人観光客が直面するストレスや障壁、例えば不安や混乱を軽減することを目的としています。日本の文化、習慣、行動、社会的規範を理解することを促進し、日本の住民には基本的なマナーを再考し、ホスピタリティの精神を育むことを呼びかけています。お互いの視点を理解し、周囲への配慮を持つことが重要であると伝えています。' where id = 'ho5j7eQml22Fevpsyv9Uh';
update content_bodies set title = 'Seeing differently - on the street -', description = 'This video addresses the stress and barriers faced by foreign tourists in Japan, such as anxiety and confusion, by promoting an understanding of Japanese culture, customs, and social norms. It also encourages Japanese residents to reflect on basic manners and the spirit of hospitality. The goal is to foster mutual understanding and consideration for different perspectives, enhancing the experience for both visitors and locals.' where id = 'RcCDn0aXrPh5Or8D2C7mz';
