update content_bodies set title = 'KANSAI JAPAN Tokushima Hyogo Tottori in 8K HDR', description = 'This video showcases the beauty of the Kansai region in Japan, specifically focusing on Tokushima, Hyogo, and Tottori. It features stunning visuals in 8K HDR, highlighting the unique landscapes and cultural aspects of these areas. For more information about Kansai, you can visit the provided link.' where id = 'NWsgV8BFaMfUlhMJP4IVk';
update content_bodies set title = '【4K】ワクワクする旅 - 魅力的な景色 - 関西、日本', description = '関西を訪れることで、なぜ数千万人の旅行者がこの地域に集まるのかを発見できます。この動画では、吉野の雲海や鳥取砂丘、奈良や京都の名所を含む美しいロケーションが紹介されています。大山の静かな風景から大阪の賑やかな街並みまで、豊かな文化と自然の驚異を体験してください。姫路城や天橋立などの歴史的な名所や、伝統的な料理も楽しめる関西の魅力的な旅にぜひご参加ください。' where id = 'y5KuytUyp5cf_3ilrYhel';
update content_bodies set title = 'The Exciting Journey - Stunning Views - KANSAI, Japan', description = 'Explore the breathtaking beauty of Kansai, Japan, a region attracting millions of travelers. This video showcases stunning locations including the Sea of Clouds in Yoshino, the Tottori Sand Dunes, and iconic temples in Nara and Kyoto. Experience the rich culture and natural wonders, from the serene landscapes of Mt. Daisen to the vibrant streets of Osaka. Discover traditional cuisine, historical sites like Himeji Castle, and the picturesque Amanohashidate. Join us on this exciting journey through Kansai, where adventure and beauty await at every turn.' where id = 'gClQzdIBCyCchMlYwoQGr';
