update content_bodies set title = 'ゴミは捨てない編', description = 'この動画は、ゴミを捨てないことについて紹介しています。環境保護やリサイクルの重要性を強調し、適切なゴミの処理方法についての意識を高める内容となっています。視聴者に対して、ゴミを適切に処理することの大切さを伝え、持続可能な社会を目指すための行動を促すことを目的としています。' where id = 'DHsicUSQpzHMwW51INpkJ';
