update content_bodies set title = '岐阜県関市「フェザーミュージアム」', description = '中部学院大学短期大学部の学生がフィールドワークを通じて、関市の観光地を取材しました。彼らは地域の魅力を探求し、観光資源の理解を深めることを目的としています。関市は多くの観光名所があり、学生たちはその中から特に注目すべきスポットを選び、訪問やインタビューを行いました。これにより、地域の文化や歴史を学びながら、観光振興に寄与することを目指しています。' where id = 'bufahDnbRC9tGXgm6EHPD';
