update content_bodies set title = '岐阜県関市「道の駅平成」', description = '中部学院大学短期大学部のフィールドワークにおいて、関市内の観光地を取材しました。この活動は、地域の魅力を再発見し、観光資源を理解することを目的としています。関市は多くの観光名所があり、地元の文化や歴史を学ぶ良い機会となりました。' where id = '3M2O0HT8XYWzOsHQpv2RP';
update content_bodies set title = 'Heisei Roadside Station in Seki City, Gifu Prefecture', description = 'Fieldwork by the Junior College Division of Chubu Gakuin University involved researching tourist attractions in Seki City.' where id = 'OVMpl25Vwiui7Or_gzJ09';
update content_bodies set title = '岐阜県関市「株杉」', description = '中部学院大学短期大学の学生がフィールドワークを通じて、関市の観光地を取材しました。関市は美しい自然や歴史的な名所が多く、学生たちは地域の魅力を発見し、観光資源の理解を深めることを目的としています。彼らの調査は、地域振興や観光業の発展に寄与することが期待されています。' where id = 'BV_mlxcgLstZX47UmfDtF';